window.RLM_FCC_LEGADO=[{"id":"tec-988714","module":"M03","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Vest (IBMEC)/IBMEC/Arquitetura e Urbanismo/2018","topic":"Raciocínio Lógico - Equivalências Lógicas (Inclui Negação de Proposições Compostas)","tecId":988714,"url":"https://www.tecconcursos.com.br/questoes/988714","page":1,"prompt":"Dadas duas proposições lógicas P e Q, então a negação da sentença P ∧ Q é equivalente a","options":{"A":"(- P) ∨ (- Q)","B":"(- P) ∧ (- Q)","C":"- (P ∨ Q)","D":"(- P) ∧ Q","E":"P ∧ (- Q)"},"answer":"A","visualRequired":false},{"id":"tec-988893","module":"M03","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Vest (IBMEC)/IBMEC/Direito/2018","topic":"Raciocínio Lógico - Equivalências Lógicas (Inclui Negação de Proposições Compostas)","tecId":988893,"url":"https://www.tecconcursos.com.br/questoes/988893","page":1,"prompt":"Dois números x e y são tais que se x > 0, então y = 1 . Conclui-se que","options":{"A":"se y ≠ 1 , então x = 0 .","B":"se x ≤ 0 , então y ≠ 1 .","C":"se y = 1 , então x > 0 .","D":"se y ≠ 1 , então x ≤ 0 .","E":"se y ≠ 1 , então x < 0 ."},"answer":"D","visualRequired":false},{"id":"tec-445343","module":"M03","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Estag (SABESP)/SABESP/Ensino Médio Técnico/2017","topic":"Raciocínio Lógico - Equivalências Lógicas (Inclui Negação de Proposições Compostas)","tecId":445343,"url":"https://www.tecconcursos.com.br/questoes/445343","page":1,"prompt":"Alguém diz: ‘se hoje a temperatura atingir mais do que 25 graus, então vai chover’. É logicamente equivalente dizer:","options":{"A":"se hoje chover, então a temperatura atingiu mais do que 25 graus.","B":"hoje chove ou a temperatura atinge mais do que 25 graus.","C":"se hoje a temperatura não atingir mais do que 25 graus, então não vai chover.","D":"se hoje não chover, então a temperatura não atinge mais do que 25 graus.","E":"hoje não chove e a temperatura não atinge mais do que 25 graus."},"answer":"D","visualRequired":false},{"id":"tec-456523","module":"M03","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - TJ TRT11/TRT 11/Administrativa/\"Sem Especialidade\"/2017","topic":"Raciocínio Lógico - Equivalências Lógicas (Inclui Negação de Proposições Compostas)","tecId":456523,"url":"https://www.tecconcursos.com.br/questoes/456523","page":1,"prompt":"A frase que corresponde à negação lógica da afirmação: Se o número de docinhos encomendados não foi o suficiente, então a festa não acabou bem, é","options":{"A":"Se o número de docinhos encomendados foi o suficiente, então a festa acabou bem.","B":"O número de docinhos encomendados não foi o suficiente e a festa acabou bem.","C":"Se a festa não acabou bem, então o número de docinhos encomendados não foi o suficiente.","D":"Se a festa acabou bem, então o número de docinhos encomendados foi o suficiente.","E":"O número de docinhos encomendados foi o suficiente e a festa não acabou bem."},"answer":"B","visualRequired":false},{"id":"tec-532524","module":"M03","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - AGP (FUNAPE)/FUNAPE/2017","topic":"Raciocínio Lógico - Equivalências Lógicas (Inclui Negação de Proposições Compostas)","tecId":532524,"url":"https://www.tecconcursos.com.br/questoes/532524","page":1,"prompt":"Considere a afirmação abaixo. Se contratei um empréstimo com juros maiores do que antes, então pagarei um montante maior. A afirmação que corresponde à negação lógica desta é","options":{"A":"Se não paguei um montante maior, então não contratei um empréstimo com juros maiores.","B":"Contratei um empréstimo com juros maiores do que antes ou pagarei um montante maior.","C":"Se contratei um empréstimo com juros menores do que antes, então pagarei um montante maior.","D":"Contratei um empréstimo com juros maiores do que antes e não pagarei um montante maior.","E":"Não contratei um empréstimo com juros maiores do que antes ou não pagarei um montante maior."},"answer":"D","visualRequired":false},{"id":"tec-539602","module":"M03","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Ana (DPE RS)/DPE RS/Jurídica/Processual/2017","topic":"Raciocínio Lógico - Equivalências Lógicas (Inclui Negação de Proposições Compostas)","tecId":539602,"url":"https://www.tecconcursos.com.br/questoes/539602","page":2,"prompt":"Considere a afirmação: Se sou descendente de italiano, então gosto de macarrão e gosto de parmesão. Uma afirmação que corresponde à negação lógica desta afirmação é","options":{"A":"Sou descendente de italiano e, não gosto de macarrão ou não gosto de parmesão.","B":"Se não sou descendente de italiano, então não gosto de macarrão e não gosto de parmesão.","C":"Se gosto de macarrão e gosto de parmesão, então não sou descendente de italiano.","D":"Não sou descendente de italiano e, gosto de macarrão e não gosto de parmesão.","E":"Se não gosto de macarrão e não gosto de parmesão, então não sou descendente de italiano."},"answer":"A","visualRequired":false},{"id":"tec-540134","module":"M03","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Ana (DPE RS)/DPE RS/Apoio Especializado (TI)/Banco de Dados/2017","topic":"Raciocínio Lógico - Equivalências Lógicas (Inclui Negação de Proposições Compostas)","tecId":540134,"url":"https://www.tecconcursos.com.br/questoes/540134","page":2,"prompt":"Considere a afirmação: Ontem trovejou e não choveu. Uma afirmação que corresponde à negação lógica desta afirmação é","options":{"A":"se ontem não trovejou, então não choveu.","B":"ontem trovejou e choveu.","C":"ontem não trovejou ou não choveu.","D":"ontem não trovejou ou choveu.","E":"se ontem choveu, então trovejou."},"answer":"D","visualRequired":false},{"id":"tec-369475","module":"M03","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - PMO (ELETROSUL)/ELETROSUL/Técnico de Segurança do Trabalho/2016","topic":"Raciocínio Lógico - Equivalências Lógicas (Inclui Negação de Proposições Compostas)","tecId":369475,"url":"https://www.tecconcursos.com.br/questoes/369475","page":2,"prompt":"A negação lógica da afirmação: “Corro bastante e não tomo chuva” é","options":{"A":"Não corro bastante e tomo chuva.","B":"Tomo chuva ou não corro bastante.","C":"Tomo chuva porque não corro bastante.","D":"Se eu corro bastante, então não tomo chuva.","E":"Corro bastante ou tomo chuva."},"answer":"B","visualRequired":false},{"id":"tec-375359","module":"M03","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Eng (COPERGÁS)/COPERGÁS/Civil/2016","topic":"Raciocínio Lógico - Equivalências Lógicas (Inclui Negação de Proposições Compostas)","tecId":375359,"url":"https://www.tecconcursos.com.br/questoes/375359","page":2,"prompt":"Se João chegar bravo em casa, então Claudete foge para o quarto e Beto não entra em casa. Uma afirmação que corresponde à negação da afirmação anterior é:","options":{"A":"João não chega bravo em casa e, Claudete não foge para o quarto ou Beto entra em casa.","B":"Se João não chega bravo em casa, então Claudete não foge para o quarto e Beto entra em casa.","C":"João chega bravo em casa e, Claudete não foge para o quarto ou Beto entra em casa.","D":"Se Claudete não foge para o quarto ou Beto entra em casa, então João não chegou em casa bravo.","E":"Se Claudete foge para o quarto e Beto não entra em casa, então João chegou bravo em casa."},"answer":"C","visualRequired":false},{"id":"tec-375974","module":"M03","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Aux (COPERGÁS)/COPERGÁS/Administrativo/2016","topic":"Raciocínio Lógico - Equivalências Lógicas (Inclui Negação de Proposições Compostas)","tecId":375974,"url":"https://www.tecconcursos.com.br/questoes/375974","page":2,"prompt":"Considere a afirmação a seguir: Se eu paguei o aluguel ou comprei comida, então o meu salário entrou na conta. Uma afirmação equivalente a afirmação anterior é","options":{"A":"Se o meu salário não entrou na conta, então eu não paguei o aluguel e não comprei comida.","B":"Se eu paguei o aluguel e comprei comida, então o meu salário entrou na conta.","C":"O meu salário entrou na conta e eu comprei comida e paguei o aluguel.","D":"Se o meu salário não entrou na conta, então eu não paguei o aluguel ou não comprei comida.","E":"Se eu não paguei o aluguel e não comprei comida, então o meu salário não entrou na conta."},"answer":"A","visualRequired":false},{"id":"tec-400513","module":"M03","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - TRE (SEFAZ MA)/SEFAZ MA/Arrecadação e Fiscalização de Mercadorias em Trânsito/2016","topic":"Raciocínio Lógico - Equivalências Lógicas (Inclui Negação de Proposições Compostas)","tecId":400513,"url":"https://www.tecconcursos.com.br/questoes/400513","page":2,"prompt":"Se a conexão com a internet cai, então não há possibilidade de comunicação. Uma afirmação que corresponde à negação lógica da afirmação anterior é:","options":{"A":"Se a conexão com a internet não cai, então há possibilidade de comunicação.","B":"Não há possibilidade de comunicação ou a conexão com a internet cai.","C":"A conexão da internet cai e há possibilidade de comunicação.","D":"Se há possibilidade de comunicação, então a conexão com a internet não cai.","E":"Ou a conexão com a internet cai, ou não há possibilidade de comunicação."},"answer":"C","visualRequired":false},{"id":"tec-410513","module":"M03","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - ALegis (ALMS)/ALMS/Administrador/2016","topic":"Raciocínio Lógico - Equivalências Lógicas (Inclui Negação de Proposições Compostas)","tecId":410513,"url":"https://www.tecconcursos.com.br/questoes/410513","page":3,"prompt":"Se João canta ou Maria sorri, então Josefa chora e Luiza não grita. Do ponto de vista lógico, uma afirmação equivalente a afirmação anterior é","options":{"A":"Se Luiza grita ou Josefa não chora, então João não canta e Maria não sorri.","B":"Se João não canta ou Maria não sorri, então Josefa não chora e Luiza grita.","C":"João canta ou Maria sorri, e Josefa não chora e Luiza grita.","D":"Se João canta, então Josefa chora e se Maria sorri, então Luiza grita.","E":"Se Luiza não grita e Josefa chora, então João canta ou Maria sorri."},"answer":"A","visualRequired":false},{"id":"tec-426184","module":"M03","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Moto (CREMESP)/CREMESP/2016","topic":"Raciocínio Lógico - Equivalências Lógicas (Inclui Negação de Proposições Compostas)","tecId":426184,"url":"https://www.tecconcursos.com.br/questoes/426184","page":3,"prompt":"Se o combustível do veículo terminou, então o motor dele desligou. Uma afirmação equivalente a esta é","options":{"A":"se o motor do veículo desligou, então o combustível dele terminou.","B":"se o motor do veículo não desligou, então o combustível dele não terminou.","C":"se o combustível do veículo não terminou, então o motor dele não desligou.","D":"o combustível do veículo terminou e o motor dele não desligou.","E":"o motor do veículo desligou e o combustível não terminou."},"answer":"B","visualRequired":false},{"id":"tec-426185","module":"M03","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Moto (CREMESP)/CREMESP/2016","topic":"Raciocínio Lógico - Equivalências Lógicas (Inclui Negação de Proposições Compostas)","tecId":426185,"url":"https://www.tecconcursos.com.br/questoes/426185","page":3,"prompt":"Marcos gosta de comer arroz com feijão e Luiza gosta de comer macarrão. A negação lógica dessa afirmação é","options":{"A":"Marcos gosta de comer arroz com feijão ou Luiza não gosta de comer macarrão.","B":"Marcos não gosta de comer macarrão e Luiza não gosta de comer arroz com feijão.","C":"Marcos não gosta de comer arroz com feijão e Luiza gosta de comer macarrão.","D":"Marcos não gosta de comer arroz com feijão ou Luiza não gosta de comer macarrão.","E":"Marcos não gosta de comer arroz com feijão ou Luiza gosta de comer macarrão."},"answer":"D","visualRequired":false},{"id":"tec-428576","module":"M03","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Adv Jr (METRO SP)/METRO SP/2016","topic":"Raciocínio Lógico - Equivalências Lógicas (Inclui Negação de Proposições Compostas)","tecId":428576,"url":"https://www.tecconcursos.com.br/questoes/428576","page":3,"prompt":"Se a gasolina acabou ou apareceu um defeito, então o motor apagou. Uma afirmação equivalente a esta é","options":{"A":"a gasolina acabou ou apareceu um defeito e o motor apagou.","B":"se o motor apagou, então a gasolina acabou ou apareceu um defeito.","C":"apareceu um defeito e a gasolina acabou e o motor não apagou.","D":"a gasolina acabou e não apareceu um defeito e o motor apagou.","E":"se o motor não apagou, então não apareceu um defeito e a gasolina não acabou."},"answer":"E","visualRequired":false},{"id":"tec-428577","module":"M03","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Adv Jr (METRO SP)/METRO SP/2016","topic":"Raciocínio Lógico - Equivalências Lógicas (Inclui Negação de Proposições Compostas)","tecId":428577,"url":"https://www.tecconcursos.com.br/questoes/428577","page":3,"prompt":"Edson não gosta de frango ou Marilda gosta de feijão e gosta de arroz. Uma afirmação que corresponda à negação lógica dessa é","options":{"A":"Marilda não gosta de arroz ou não gosta de feijão e Edson gosta de frango.","B":"Edson gosta de frango e Marilda não gosta de feijão e não gosta de arroz.","C":"Se Edson não gosta de frango, então Marilda gosta de feijão e arroz.","D":"Se Marilda não gosta de feijão e arroz, então Edson gosta de frango.","E":"Edson gosta de arroz e Marilda gosta de frango e feijão."},"answer":"A","visualRequired":false},{"id":"tec-429005","module":"M03","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Aux Enf T (METRO SP)/METRO SP/2016","topic":"Raciocínio Lógico - Equivalências Lógicas (Inclui Negação de Proposições Compostas)","tecId":429005,"url":"https://www.tecconcursos.com.br/questoes/429005","page":3,"prompt":"A proposição “se tem mais de 10 anos de experiência, então está habilitado para o cargo de gerência” é equivalente, do ponto de vista da lógica, a","options":{"A":"se não está habilitado para o cargo de gerência, então não tem mais de 10 anos de experiência.","B":"se não tem mais de 10 anos de experiência, então não está habilitado para o cargo de gerência.","C":"tem mais de 10 anos de experiência e não está habilitado para o cargo de gerência.","D":"está habilitado para o cargo de gerência e não tem mais de 10 anos de experiência.","E":"ou tem mais de 10 anos ou está habilitado para o cargo de gerência."},"answer":"A","visualRequired":false},{"id":"tec-429007","module":"M03","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Aux Enf T (METRO SP)/METRO SP/2016","topic":"Raciocínio Lógico - Equivalências Lógicas (Inclui Negação de Proposições Compostas)","tecId":429007,"url":"https://www.tecconcursos.com.br/questoes/429007","page":4,"prompt":"Se a proposição “Laura estuda de dia e trabalha de noite” é falsa, do ponto de vista da lógica é verdade que Laura","options":{"A":"estuda de noite e trabalha de dia.","B":"não estuda de dia nem trabalha de noite.","C":"não estuda de dia ou trabalha de noite.","D":"não estuda de dia ou não trabalha de noite.","E":"estuda de noite ou trabalha de dia."},"answer":"D","visualRequired":false},{"id":"tec-429499","module":"M03","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Op TM (METRO SP)/METRO SP/2016","topic":"Raciocínio Lógico - Equivalências Lógicas (Inclui Negação de Proposições Compostas)","tecId":429499,"url":"https://www.tecconcursos.com.br/questoes/429499","page":4,"prompt":"A negação da proposição “as aranhas são insetos e são noturnas”, é: as aranhas","options":{"A":"são insetos ou não são noturnas.","B":"não são insetos ou são noturnas.","C":"são insetos ou são noturnas.","D":"não são insetos e não são noturnas.","E":"não são insetos ou não são noturnas."},"answer":"E","visualRequired":false},{"id":"tec-437806","module":"M03","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - AJ TRT20/TRT 20/Administrativa/\"Sem Especialidade\"/2016","topic":"Raciocínio Lógico - Equivalências Lógicas (Inclui Negação de Proposições Compostas)","tecId":437806,"url":"https://www.tecconcursos.com.br/questoes/437806","page":4,"prompt":"Do ponto de vista da lógica, a proposição “se tem OAB, então é advogado” é equivalente à","options":{"A":"tem OAB ou é advogado.","B":"se não tem OAB, então não é advogado.","C":"se não é advogado, então não tem OAB.","D":"é advogado e não tem OAB.","E":"se é advogado, então tem OAB."},"answer":"C","visualRequired":false},{"id":"tec-621387","module":"M03","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Ass Adm (SANASA)/SANASA/2016","topic":"Raciocínio Lógico - Equivalências Lógicas (Inclui Negação de Proposições Compostas)","tecId":621387,"url":"https://www.tecconcursos.com.br/questoes/621387","page":4,"prompt":"Do ponto de vista da lógica, a negação da proposição “Laura é economista e trabalha na SANASA” é","options":{"A":"Laura não é economista ou não trabalha na SANASA.","B":"Laura é economista e não trabalha na SANASA.","C":"Laura não é economista ou trabalha da SANASA.","D":"Laura é economista ou trabalha na SANASA.","E":"Laura não é economista e não trabalha na SANASA."},"answer":"A","visualRequired":false},{"id":"tec-621633","module":"M03","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Ag Mec MA (SANASA)/SANASA/Motor Diesel/2016","topic":"Raciocínio Lógico - Equivalências Lógicas (Inclui Negação de Proposições Compostas)","tecId":621633,"url":"https://www.tecconcursos.com.br/questoes/621633","page":4,"prompt":"Se João saiu muito cedo de casa, então ele conseguiu chegar primeiro ao banco. Uma NEGAÇÃO lógica dessa afirmação é:","options":{"A":"João não saiu muito cedo de casa e não conseguiu chegar primeiro ao banco.","B":"Ou João saiu muito cedo de casa, ou ele conseguiu chegar primeiro ao banco.","C":"João saiu muito cedo de casa e ele não conseguiu chegar primeiro ao banco.","D":"Se João não chegou primeiro ao banco, então ele não saiu muito cedo de casa.","E":"Se João chegou primeiro ao banco, então ele saiu muito cedo de casa."},"answer":"C","visualRequired":false},{"id":"tec-263315","module":"M03","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - JATTE (SEFAZ PE)/SEFAZ PE/2015","topic":"Raciocínio Lógico - Equivalências Lógicas (Inclui Negação de Proposições Compostas)","tecId":263315,"url":"https://www.tecconcursos.com.br/questoes/263315","page":4,"prompt":"Observe a afirmação a seguir, feita pelo prefeito de uma grande capital. Se a inflação não cair ou o preço do óleo diesel aumentar, então o preço das passagens de ônibus será reajustado. Uma maneira logicamente equivalente de fazer esta afirmação é:","options":{"A":"Se a inflação cair e o preço do óleo diesel não aumentar, então o preço das passagens de ônibus não será reajustado.","B":"Se a inflação cair ou o preço do óleo diesel aumentar, então o preço das passagens de ônibus não será reajustado.","C":"Se o preço das passagens de ônibus for reajustado, então a inflação não terá caído ou o preço do óleo diesel terá aumentado.","D":"Se o preço das passagens de ônibus não for reajustado, então a inflação terá caído ou o preço do óleo diesel terá aumentado.","E":"Se o preço das passagens de ônibus não for reajustado, então a inflação terá caído e o preço do óleo diesel não terá aumentado."},"answer":"E","visualRequired":false},{"id":"tec-272744","module":"M03","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - AP (MANAUSPREV)/MANAUSPREV/Administrativa/2015","topic":"Raciocínio Lógico - Equivalências Lógicas (Inclui Negação de Proposições Compostas)","tecId":272744,"url":"https://www.tecconcursos.com.br/questoes/272744","page":5,"prompt":"Considere a afirmação: Se os impostos sobem, então o consumo cai e a inadimplência aumenta. Uma afirmação que corresponde à negação lógica dessa afirmação é","options":{"A":"Se o consumo não cai ou a inadimplência não aumenta, então os impostos não sobem.","B":"Os impostos sobem e o consumo não cai ou a inadimplência não aumenta.","C":"Se os impostos não sobem, então o consumo aumenta e a inadimplência cai.","D":"Os impostos não sobem e o consumo não cai e a inadimplência não aumenta.","E":"Se os impostos não sobem, então o consumo não cai e a inadimplência não aumenta."},"answer":"B","visualRequired":false},{"id":"tec-283220","module":"M03","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - TCE (TCE-CE)/TCE CE/Controle Externo/Auditoria de Tecnologia da Informação/2015","topic":"Raciocínio Lógico - Equivalências Lógicas (Inclui Negação de Proposições Compostas)","tecId":283220,"url":"https://www.tecconcursos.com.br/questoes/283220","page":5,"prompt":"Dois amigos estavam conversando sobre exercícios físicos quando um deles disse: “Se você fizer esteira, então você emagrecerá e melhorará o condicionamento físico”. O outro amigo, para negar a afirmação, deverá dizer:","options":{"A":"Faça esteira e você não emagrecerá e não melhorará o condicionamento físico.","B":"Faça esteira e você não emagrecerá ou não melhorará o condicionamento físico.","C":"Se você fizer esteira e não emagrecer, então não vai melhorar o condicionamento físico.","D":"Faça esteira e você emagrecerá e não melhorará o condicionamento físico.","E":"Se você fizer esteira e emagrecer, então não melhorará o condicionamento físico."},"answer":"B","visualRequired":false},{"id":"tec-283223","module":"M03","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - TCE (TCE-CE)/TCE CE/Controle Externo/Auditoria de Tecnologia da Informação/2015","topic":"Raciocínio Lógico - Equivalências Lógicas (Inclui Negação de Proposições Compostas)","tecId":283223,"url":"https://www.tecconcursos.com.br/questoes/283223","page":5,"prompt":"A afirmação que é logicamente equivalente à afirmação: \"Se faço karatê, então sei me defender” é","options":{"A":"Se não faço karatê, então não sei me defender.","B":"Se sei me defender, então faço karatê.","C":"Se não sei me defender, então não faço karatê.","D":"Se não sei me defender, então faço karatê.","E":"Se faço karatê, então não sei me defender."},"answer":"C","visualRequired":false},{"id":"tec-283224","module":"M03","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - TCE (TCE-CE)/TCE CE/Controle Externo/Auditoria de Tecnologia da Informação/2015","topic":"Raciocínio Lógico - Equivalências Lógicas (Inclui Negação de Proposições Compostas)","tecId":283224,"url":"https://www.tecconcursos.com.br/questoes/283224","page":5,"prompt":"Um casal está no supermercado fazendo compras do mês e o marido diz para a esposa: “Vamos comprar macarrão ou arroz integral”. A esposa negando a afirmação diz:","options":{"A":"Se vamos comprar macarrão, então não vamos comprar arroz integral.","B":"Não vamos comprar macarrão ou não vamos comprar arroz integral.","C":"Se não vamos comprar macarrão, então não vamos comprar arroz integral.","D":"Não vamos comprar macarrão e não vamos comprar arroz integral.","E":"Se não vamos comprar macarrão, então vamos comprar arroz integral."},"answer":"D","visualRequired":false},{"id":"tec-325596","module":"M03","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Aux Adm (DPE RR)/DPE RR/2015","topic":"Raciocínio Lógico - Equivalências Lógicas (Inclui Negação de Proposições Compostas)","tecId":325596,"url":"https://www.tecconcursos.com.br/questoes/325596","page":5,"prompt":"Maria disse: Gerusa estava doente e não foi trabalhar. Sabe-se que Maria mentiu. Sendo assim, é correto afirmar que","options":{"A":"Gerusa não estava doente, mas não foi trabalhar.","B":"Gerusa não estava doente e não foi trabalhar.","C":"Gerusa não estava doente ou foi trabalhar.","D":"se Gerusa foi trabalhar, então não estava doente.","E":"Gerusa estava doente ou foi trabalhar."},"answer":"C","visualRequired":false},{"id":"tec-326004","module":"M03","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Aux Tec Fis (TCE-SP)/TCE SP/\"Sem Área\"/2015","topic":"Raciocínio Lógico - Equivalências Lógicas (Inclui Negação de Proposições Compostas)","tecId":326004,"url":"https://www.tecconcursos.com.br/questoes/326004","page":5,"prompt":"Considere a afirmação: Se Kléber é escritor, então ou João é biólogo ou é matemático. Uma afirmação equivalente é:","options":{"A":"Se João não é biólogo e é matemático, então Kléber não é escritor.","B":"Se João não é biólogo nem matemático ou se João é biólogo e matemático, então Kléber não é escritor.","C":"Se João é biólogo e não é matemático, então Kléber não é escritor.","D":"Se João é biólogo e não é matemático ou se João não é biólogo e é matemático, então Kléber não é escritor.","E":"Se João é biólogo e matemático, então Kléber é escritor."},"answer":"B","visualRequired":false},{"id":"tec-172375","module":"M03","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - TJ TRF3/TRF 3/Administrativa/Agente da Policia Judicial/2014","topic":"Raciocínio Lógico - Equivalências Lógicas (Inclui Negação de Proposições Compostas)","tecId":172375,"url":"https://www.tecconcursos.com.br/questoes/172375","page":6,"prompt":"Considere a afirmação: Nem todas as exigências foram cumpridas ou o processo segue adiante. Do ponto de vista lógico, uma afirmação equivalente à acima é:","options":{"A":"Se o processo segue adiante, então nem todas as exigências foram cumpridas.","B":"O processo não segue adiante e todas as exigências foram cumpridas.","C":"Se todas as exigências foram cumpridas, então o processo segue adiante.","D":"Se nenhuma exigência foi cumprida, então o processo não segue adiante.","E":"Nem todas as exigências foram cumpridas e o processo segue adiante."},"answer":"C","visualRequired":false},{"id":"tec-173686","module":"M03","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - TJ TRT19/TRT 19/Administrativa/\"Sem Especialidade\"/2014","topic":"Raciocínio Lógico - Equivalências Lógicas (Inclui Negação de Proposições Compostas)","tecId":173686,"url":"https://www.tecconcursos.com.br/questoes/173686","page":6,"prompt":"Considere a seguinte afirmação: Se José estuda com persistência, então ele faz uma boa prova e fica satisfeito. Uma afirmação que é a negação da afirmação acima é","options":{"A":"José estuda com persistência e ele não faz uma boa prova e ele não fica satisfeito.","B":"José não estuda com persistência e ele não faz uma boa prova ou fica satisfeito.","C":"José estuda com persistência ou ele faz uma boa prova ou ele não fica satisfeito.","D":"José estuda com persistência e ele não faz uma boa prova ou ele não fica satisfeito.","E":"Se José fica satisfeito então ele fez uma boa prova e estudou com persistência."},"answer":"D","visualRequired":false},{"id":"tec-200688","module":"M03","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - TJ TRT16/TRT 16/Apoio Especializado/Tecnologia da Informação/2014","topic":"Raciocínio Lógico - Equivalências Lógicas (Inclui Negação de Proposições Compostas)","tecId":200688,"url":"https://www.tecconcursos.com.br/questoes/200688","page":6,"prompt":"Não gosto de ficar em casa e vou ao cinema todos os dias. Do ponto de vista lógico, uma afirmação que corresponde a uma negação dessa afirmação é:","options":{"A":"Não gosto de sair de casa e não vou ao cinema todos os dias.","B":"Vou ao cinema todos os dias e gosto de ficar em casa.","C":"Não vou ao cinema todos os dias ou não gosto de ficar em casa.","D":"Se não gosto de ficar em casa, então vou ao cinema todos os dias.","E":"Gosto de ficar em casa ou não vou ao cinema todos os dias."},"answer":"E","visualRequired":false},{"id":"tec-212604","module":"M03","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - AJ TRF4/TRF 4/Apoio Especializado/Análise de Sistemas de Informação/2014","topic":"Raciocínio Lógico - Equivalências Lógicas (Inclui Negação de Proposições Compostas)","tecId":212604,"url":"https://www.tecconcursos.com.br/questoes/212604","page":6,"prompt":"Um economista afirmou, no telejornal, que “se os impostos não sobem, então a receita fiscal não cresce”. Do ponto de vista da lógica, uma frase equivalente a essa é","options":{"A":"se a receita fiscal cresce, então os impostos sobem.","B":"se os impostos sobem, então a receita fiscal cresce.","C":"se a receita fiscal não cresce, então os impostos não sobem.","D":"ou o imposto não sobe, ou a receita cresce.","E":"o imposto sobe sempre que a receita fiscal aumenta"},"answer":"A","visualRequired":false},{"id":"tec-252561","module":"M03","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - TJ (TRF 1ª Região)/TRF 1/Apoio Especializado/Informática/2014","topic":"Raciocínio Lógico - Equivalências Lógicas (Inclui Negação de Proposições Compostas)","tecId":252561,"url":"https://www.tecconcursos.com.br/questoes/252561","page":6,"prompt":"A embalagem de pão de forma indica que o produto “não contém açúcar e gordura”. De acordo com o significado do conectivo “e” no estudo da lógica, é correto afirmar, a respeito desse pão de forma, que ele","options":{"A":"não contém açúcar, mas contém gordura.","B":"não contém gordura, mas contém açúcar.","C":"necessariamente não contém açúcar, e não contém gordura.","D":"pode conter açúcar.","E":"não pode conter gordura."},"answer":"D","visualRequired":false},{"id":"tec-478428","module":"M03","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Ag Leg (ALEPE)/ALEPE/2014","topic":"Raciocínio Lógico - Equivalências Lógicas (Inclui Negação de Proposições Compostas)","tecId":478428,"url":"https://www.tecconcursos.com.br/questoes/478428","page":7,"prompt":"A negação da frase “Ele não é artista, nem jogador de futebol” é equivalente a","options":{"A":"ele é artista ou jogador de futebol.","B":"ele é artista ou não é jogador de futebol.","C":"não é certo que ele seja artista e jogador de futebol.","D":"ele é artista e jogador de futebol.","E":"ele não é artista ou não é jogador de futebol."},"answer":"A","visualRequired":false},{"id":"tec-1021470","module":"M03","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Per (DPT BA)/DPT BA/Técnico de Polícia Civil/2014","topic":"Raciocínio Lógico - Equivalências Lógicas (Inclui Negação de Proposições Compostas)","tecId":1021470,"url":"https://www.tecconcursos.com.br/questoes/1021470","page":7,"prompt":"Renata disse a seguinte frase: “Se Lucas venceu o jogo, então Denis não compareceu”. Lucas, irado, afirmou que a frase dita por Renata não era verdadeira. Uma frase, que do ponto de vista lógico, é a negação da frase dita por Renata é:","options":{"A":"Lucas venceu o jogo ou Denis venceu o jogo.","B":"Denis não compareceu ao jogo e Lucas não venceu.","C":"Lucas venceu o jogo e Denis compareceu.","D":"Se Lucas não venceu o jogo, então Denis compareceu.","E":"Lucas venceu o jogo ou Denis compareceu."},"answer":"C","visualRequired":false},{"id":"tec-2637979","module":"M03","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - AJ (TJ AP)/TJ AP/Judiciária/Execução de Mandados/2014","topic":"Raciocínio Lógico - Equivalências Lógicas (Inclui Negação de Proposições Compostas)","tecId":2637979,"url":"https://www.tecconcursos.com.br/questoes/2637979","page":7,"prompt":"Considere a seguinte declaração, feita por um analista político fictício: “se o partido P conseguir eleger Senador no Estado F ou no Estado G, então terá a maioria no Senado”. A partir da declaração do analista, é correto concluir que, necessariamente, se o partido P","options":{"A":"não tiver a maioria no Senado, então não terá conseguido eleger o senador no Estado G.","B":"tiver a maioria no Senado, então terá conseguido eleger o senador no Estado G.","C":"tiver a maioria no Senado, então terá conseguido eleger o senador no Estado F.","D":"não conseguiu eleger o senador no Estado F, então não terá a maioria no Senado.","E":"não conseguiu eleger o senador no Estado G, então não terá a maioria no Senado."},"answer":"A","visualRequired":false},{"id":"tec-2637995","module":"M03","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - AJ (TJ AP)/TJ AP/Judiciária/Execução de Mandados/2014","topic":"Raciocínio Lógico - Equivalências Lógicas (Inclui Negação de Proposições Compostas)","tecId":2637995,"url":"https://www.tecconcursos.com.br/questoes/2637995","page":7,"prompt":"No Brasil, o voto é obrigatório apenas para os brasileiros alfabetizados que têm de 18 a 70 anos. De acordo com essa informação, se Luíza é uma brasileira que não é obrigada a votar, então, necessariamente, Luíza","options":{"A":"é analfabeta e tem menos de 18 anos ou mais de 70.","B":"é analfabeta ou tem menos de 18 anos ou mais de 70.","C":"não é analfabeta, mas tem menos de 18 anos.","D":"é analfabeta, mas pode ter de 18 a 70 anos.","E":"tem mais de 70 anos, mas pode não ser analfabeta."},"answer":"B","visualRequired":false},{"id":"tec-2638138","module":"M03","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - TJ (TJ AP)/TJ AP/Judiciária e Administrativa/2014","topic":"Raciocínio Lógico - Equivalências Lógicas (Inclui Negação de Proposições Compostas)","tecId":2638138,"url":"https://www.tecconcursos.com.br/questoes/2638138","page":7,"prompt":"Vou à academia todos os dias da semana e corro três dias na semana. Uma afirmação que corresponde à negação lógica da afirmação anterior é","options":{"A":"Não vou à academia todos os dias da semana ou não corro três dias na semana.","B":"Vou à academia quase todos os dias da semana e corro dois dias na semana.","C":"Nunca vou à academia durante a semana e nunca corro durante a semana.","D":"Não vou à academia todos os dias da semana e não corro três dias na semana.","E":"Se vou todos os dias à academia, então corro três dias na semana."},"answer":"A","visualRequired":false},{"id":"tec-151289","module":"M03","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Ana Gov (SEAD PI)/SEAD PI/Planejamento e Orçamento/2013","topic":"Raciocínio Lógico - Equivalências Lógicas (Inclui Negação de Proposições Compostas)","tecId":151289,"url":"https://www.tecconcursos.com.br/questoes/151289","page":7,"prompt":"Se Heráclito está convicto de que o mundo está em permanente mudança, então ele é triste. Portanto, se","options":{"A":"Heráclito não está convicto de que o mundo está em permanente mudança, então ele é triste.","B":"Heráclito está convicto de que o mundo está em permanente mudança, então ele não é triste.","C":"Heráclito não é triste, então ele não está convicto de que o mundo está em permanente mudança.","D":"Heráclito é triste, então ele não está convicto de que o mundo está em permanente mudança.","E":"Heráclito é triste, o mundo está em permanente mudança."},"answer":"C","visualRequired":false},{"id":"tec-173008","module":"M03","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - AJ TRT5/TRT 5/Judiciária/\"Sem Especialidade\"/2013","topic":"Raciocínio Lógico - Equivalências Lógicas (Inclui Negação de Proposições Compostas)","tecId":173008,"url":"https://www.tecconcursos.com.br/questoes/173008","page":7,"prompt":"Devido à proximidade das eleições, foi decidido que os tribunais eleitorais deveriam funcionar, em regime de plantão, durante um determinado domingo do ano. Em relação a esse plantão, foi divulgada a seguinte orientação: “Se todos os processos forem analisados até às 11 horas, então o plantão será finalizado nesse horário.” Considere que a orientação foi cumprida e que o plantão só foi finalizado às 18 horas. Então, pode-se concluir que, necessariamente,","options":{"A":"nenhum processo foi analisado até às 11 horas.","B":"todos os processos foram analisados até às 11 horas.","C":"pelo menos um processo terminou de ser analisado às 18 horas.","D":"todos os processos foram analisados até às 18 horas.","E":"pelo menos um processo não foi analisado até às 11 horas."},"answer":"E","visualRequired":false},{"id":"tec-173053","module":"M03","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - TJ TRT5/TRT 5/Apoio Especializado/Tecnologia da Informação/2013","topic":"Raciocínio Lógico - Equivalências Lógicas (Inclui Negação de Proposições Compostas)","tecId":173053,"url":"https://www.tecconcursos.com.br/questoes/173053","page":8,"prompt":"Analisando a tabela de classificação do campeonato de futebol amador do bairro antes da realização da última rodada, o técnico do União concluiu que, caso seu time vencesse sua última partida ou o time do Camisa não ganhasse seu último jogo, então o União seria campeão. Sabendo que o União não se sagrou campeão, pode- se concluir que, necessariamente,","options":{"A":"o Camisa perdeu seu jogo e o União perdeu o seu.","B":"o Camisa venceu seu jogo e o União venceu o seu.","C":"o Camisa empatou seu jogo e o União empatou ou perdeu o seu.","D":"o Camisa empatou seu jogo e o União venceu o seu.","E":"o Camisa venceu seu jogo e o União empatou ou perdeu o seu."},"answer":"E","visualRequired":false},{"id":"tec-173178","module":"M03","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - AJ TRT5/TRT 5/Judiciária/Oficial de Justiça Avaliador Federal/2013","topic":"Raciocínio Lógico - Equivalências Lógicas (Inclui Negação de Proposições Compostas)","tecId":173178,"url":"https://www.tecconcursos.com.br/questoes/173178","page":8,"prompt":"Leia a instrução fictícia reproduzida a seguir e suponha que ela seja sempre cumprida. “Sempre que um Oficial de Justiça executar uma intimação, ele deverá estar acompanhado por um Policial Federal.” Nessas condições, é correto concluir que, necessariamente,","options":{"A":"os Oficiais de Justiça deverão estar acompanhados por um Policial Federal durante todo seu horário de trabalho.","B":"um Oficial de Justiça só deverá solicitar o acompanhamento de um Policial Federal quando for executar uma intimação.","C":"sempre que um Oficial de Justiça estiver acompanhado por um policial, ele deverá estar executando uma intimação.","D":"se um Oficial de Justiça não estiver executando uma intimação, então ele não poderá estar acompanhado por um Policial Federal.","E":"se um Oficial de Justiça não estiver acompanhado por um Policial Federal, então ele não estará executando uma intimação."},"answer":"E","visualRequired":false},{"id":"tec-178832","module":"M03","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Ana Proc (PGE BA)/PGE BA/Calculista/2013","topic":"Raciocínio Lógico - Equivalências Lógicas (Inclui Negação de Proposições Compostas)","tecId":178832,"url":"https://www.tecconcursos.com.br/questoes/178832","page":8,"prompt":"Ao se admitir por verdadeira a declaração “Se Paulo é alto, então Gabriela não é alta”, conclui-se, de maneira correta e necessária, que se","options":{"A":"Gabriela é alta, então Paulo não é alto.","B":"Gabriela é alta, então Paulo é alto.","C":"Gabriela não é alta, então Paulo não é alto.","D":"Gabriela não é alta, então Paulo é Gabriela.","E":"Paulo não é alto, então Gabriela é maior que Paulo."},"answer":"A","visualRequired":false},{"id":"tec-179336","module":"M03","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Ass Proc (PGE BA)/PGE BA/2013","topic":"Raciocínio Lógico - Equivalências Lógicas (Inclui Negação de Proposições Compostas)","tecId":179336,"url":"https://www.tecconcursos.com.br/questoes/179336","page":8,"prompt":"A negação de “Ruy Barbosa é abolicionista e Senador Dantas é baiano” é:","options":{"A":"Ruy Barbosa não é abolicionista e Senador Dantas não é baiano.","B":"Ruy Barbosa é baiano e Senador Dantas é abolicionista.","C":"Ruy Barbosa não é abolicionista ou Senador Dantas não é baiano.","D":"Ruy Barbosa é baiano ou Senador Dantas não é abolicionista.","E":"Ruy Barbosa é Senador Dantas e Senador Dantas é Ruy Barbosa."},"answer":"C","visualRequired":false},{"id":"tec-1407497","module":"M03","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Ag Ap (MPE AM)/MPE AM/Administrativo/2013","topic":"Raciocínio Lógico - Equivalências Lógicas (Inclui Negação de Proposições Compostas)","tecId":1407497,"url":"https://www.tecconcursos.com.br/questoes/1407497","page":8,"prompt":"O professor de uma disciplina experimental de um curso de Engenharia estabeleceu no início do semestre que, para ser aprovado, um aluno teria de realizar pelo menos 5 das 6 experiências propostas e ter média de relatórios maior ou igual a 6,0. Como Juca foi reprovado nessa disciplina, pode-se concluir que ele, necessariamente,","options":{"A":"realizou apenas 4 experiências e teve média de relatórios, no máximo, igual a 5,0.","B":"realizou 4 ou menos experiências e teve média de relatórios inferior a 6,0.","C":"realizou menos do que 5 experiências ou teve média de relatórios inferior a 6,0.","D":"não realizou qualquer experiência, tendo média de relatórios igual a 0,0.","E":"não realizou qualquer experiência ou teve média de relatórios menor ou igual a 5,0."},"answer":"C","visualRequired":false},{"id":"tec-89921","module":"M03","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - TJ TST/TST/Apoio Especializado/Tecnologia da Informação/2012","topic":"Raciocínio Lógico - Equivalências Lógicas (Inclui Negação de Proposições Compostas)","tecId":89921,"url":"https://www.tecconcursos.com.br/questoes/89921","page":9,"prompt":"A Seguradora Sossego veiculou uma propaganda cujo slogan era: “Sempre que o cliente precisar, terá Sossego ao seu lado.” Considerando que o slogan seja verdadeiro, conclui-se que, necessariamente, se o cliente","options":{"A":"não precisar, então não terá Sossego ao seu lado.","B":"não precisar, então terá Sossego ao seu lado.","C":"não tiver Sossego ao seu lado, então não precisou.","D":"tiver Sossego ao seu lado, então não precisou.","E":"tiver Sossego ao seu lado, então precisou."},"answer":"C","visualRequired":false},{"id":"tec-432398","module":"M03","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Sold (PM BA)/PM BA/2012","topic":"Raciocínio Lógico - Equivalências Lógicas (Inclui Negação de Proposições Compostas)","tecId":432398,"url":"https://www.tecconcursos.com.br/questoes/432398","page":9,"prompt":"A negação da afirmação: “Estou com saúde e sou feliz” é","options":{"A":"Não estou com saúde ou sou feliz.","B":"Não estou com saúde ou não sou feliz.","C":"Não estou feliz e estou com saúde.","D":"Não estou com saúde e estou feliz.","E":"Estou com saúde ou não sou feliz,"},"answer":"B","visualRequired":false},{"id":"tec-432410","module":"M03","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Sold (PM BA)/PM BA/2012","topic":"Raciocínio Lógico - Equivalências Lógicas (Inclui Negação de Proposições Compostas)","tecId":432410,"url":"https://www.tecconcursos.com.br/questoes/432410","page":9,"prompt":"A negação lógica da proposição: \"Pedro é o mais velho da classe ou Jorge é o mais novo da classe\" é","options":{"A":"Pedro não è o mais novo da classe ou Jorge não é o mais velho da classe.","B":"Pedro é o mais velho da classe e Jorge não é o mais novo da classe.","C":"Pedro não é o mais velho da classe e Jorge não é o mais novo da classe.","D":"Pedro não é o mais novo da classe e Jorge não é o mais velho da classe.","E":"Pedro é o mais novo da classe ou Jorge é o mais novo da classe."},"answer":"C","visualRequired":false},{"id":"tec-974091","module":"M03","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Tec Ban III (BANESE)/BANESE/Informática/Desenvolvimento/2012","topic":"Raciocínio Lógico - Equivalências Lógicas (Inclui Negação de Proposições Compostas)","tecId":974091,"url":"https://www.tecconcursos.com.br/questoes/974091","page":9,"prompt":"De acordo com o novo projeto implantado pelo setor de informática de um banco, sempre que o sistema integrado principal cair, o sistema auxiliar estará pronto para entrar em funcionamento. Considerando que essa informação esteja correta, pode-se concluir que, necessariamente,","options":{"A":"o sistema auxiliar só estará pronto para entrar em funcionamento quando o sistema integrado principal cair.","B":"o sistema integrado principal cairá sempre que o sistema auxiliar estiver pronto para entrar em funcionamento.","C":"se o sistema integrado principal não cair, então o sistema auxiliar não estará pronto para entrar em funcionamento.","D":"se o sistema auxiliar não estiver pronto para entrar em funcionamento, então o sistema integrado principal não terá caído.","E":"se o sistema auxiliar estiver pronto para entrar em funcionamento, então o sistema integrado principal terá caído."},"answer":"D","visualRequired":false},{"id":"tec-263318","module":"M03","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - JATTE (SEFAZ PE)/SEFAZ PE/2015","topic":"Raciocínio Lógico - Álgebra de Proposições","tecId":263318,"url":"https://www.tecconcursos.com.br/questoes/263318","page":9,"prompt":"Antes da rodada final do campeonato inglês de futebol, um comentarista esportivo apresentou a situação das duas únicas equipes com chances de serem campeãs, por meio da seguinte afirmação: “Para que o Arsenal seja campeão, é necessário que ele vença sua partida e que o Chelsea perca ou empate a sua.” Uma maneira equivalente, do ponto de vista lógico, de apresentar esta informação é: “Para que o Arsenal seja campeão, é necessário que ele","options":{"A":"vença sua partida e o Chelsea perca a sua ou que ele vença a sua partida e o Chelsea empate a sua.”","B":"vença sua partida ou o Chelsea perca a sua ou que ele vença a sua partida ou o Chelsea empate a sua.”","C":"empate sua partida e o Chelsea perca a sua ou que ele vença a sua partida e o Chelsea não vença a sua.”","D":"vença sua partida e o Chelsea perca a sua e que ele vença a sua partida e o Chelsea empate a sua.”","E":"vença sua partida ou o Chelsea perca a sua e que ele vença a sua partida ou o Chelsea empate a sua.”"},"answer":"A","visualRequired":false},{"id":"tec-3863131","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - FTE (SEFAZ MT)/SEFAZ MT/2026","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":3863131,"url":"https://www.tecconcursos.com.br/questoes/3863131","page":9,"prompt":"André, Breno, Carla, Denise e Érica são os responsáveis pela manutenção dos servidores em certo Data Center. Essas pessoas se revezam em turnos de trabalho, de maneira que, em cada turno, deve haver exatamente 3 pessoas presentes. Em certo turno, Érica estava presente e fez as seguintes anotações: Breno não está de folga ou Carla está de folga. André não está de folga e Denise está de folga. Ou Breno não está de folga ou Denise não está de folga. Se Carla está de folga, então Denise não está de folga. André não está de folga se, e somente se, Breno não está de folga. Sabendo que exatamente uma das anotações feitas por Érica é logicamente falsa, então é logicamente verdadeiro que:","options":{"A":"Se Carla está de folga, então André está de folga ou Denise não está de folga.","B":"Breno não está de folga se, e somente se, Carla não está de folga.","C":"André ou Breno estavam de folga.","D":"Carla e Denise estavam de folga.","E":"Ou André está de folga ou Carla não está de folga."},"answer":"D","visualRequired":false},{"id":"tec-3357836","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Ana (Pref SP)/Pref SP/Planejamento e Desenvolvimento Organizacional/Tecnologia da Informação e Comunicação/2025","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":3357836,"url":"https://www.tecconcursos.com.br/questoes/3357836","page":10,"prompt":"Se Zum não vai a lugar algum, então Zum não está selado. Se Zum vai a algum lugar, então Zum está registrado ou Zum está carimbado. Sempre que Zum está selado, Zum não está rotulado. Se Zum está registrado, então Zum está rotulado. Ontem, Zum estava selado, portanto, ontem, Zum","options":{"A":"não foi a lugar algum e estava selado.","B":"não foi a lugar algum ou estava registrado.","C":"foi a algum lugar e estava carimbado.","D":"foi a algum lugar e estava registrado.","E":"não foi a lugar algum ou estava rotulado."},"answer":"C","visualRequired":false},{"id":"tec-3567483","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Aud Gov (CGE PI)/CGE PI/Tecnologia da Informação/2025","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":3567483,"url":"https://www.tecconcursos.com.br/questoes/3567483","page":10,"prompt":"Há quatro cartões diferentes sobre uma mesa. Cada cartão possui uma letra de um lado e um número natural do outro. As faces visíveis dos cartões mostram os seguintes símbolos: E, K, 2 e 7. Deseja-se verificar se a seguinte regra está sendo obedecida: \"Se houver um número par em um dos lados do cartão, então necessariamente há uma vogal no outro lado.\" Existe um conjunto mínimo e correto de cartões para verificar essa regra, que seria virar","options":{"A":"os cartões com os símbolos E e 7.","B":"somente o cartão com o número 2.","C":"os cartões com os símbolos E e 2.","D":"os cartões com os símbolos K e 7.","E":"os cartões com os símbolos K e 2."},"answer":"E","visualRequired":false},{"id":"tec-3682994","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Of (CBM AP)/CBM AP/Combatente/2025","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":3682994,"url":"https://www.tecconcursos.com.br/questoes/3682994","page":10,"prompt":"Nos dias em que não é feriado, à oficial Patrícia treina atletismo em seu clube e veste roupa azul. Se estiver chovendo, não há treino de corrida no clube que a oficial Patrícia frequenta. Neste momento ocorre um treino de corrida no clube da oficial Patrícia, portanto, é logicamente verdadeiro que","options":{"A":"a oficial Patrícia está treinando atletismo, mas não corrida.","B":"não é feriado e a oficial Patrícia veste roupa azul.","C":"não está chovendo.","D":"é feriado e a oficial Patrícia não veste roupa azul,","E":"a oficial Patrícia está treinando corrida."},"answer":"C","visualRequired":false},{"id":"tec-2113968","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - AJ TRT4/TRT 4/Judiciária/\"Sem Especialidade\"/2022","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":2113968,"url":"https://www.tecconcursos.com.br/questoes/2113968","page":10,"prompt":"Quando estou feliz e faz sol, passeio com o cachorro. Sempre que passeio com o cachorro e não passo na padaria, como um pastel na feira. Ontem, não comi um pastel na feira e não passei na padaria. Logo, ontem, necessariamente,","options":{"A":"eu não estava feliz.","B":"fez sol.","C":"não passeei com o cachorro.","D":"eu estava feliz.","E":"passeei com o cachorro."},"answer":"C","visualRequired":false},{"id":"tec-2114108","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - TJ TRT4/TRT 4/Apoio Especializado/Enfermagem do Trabalho/2022","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":2114108,"url":"https://www.tecconcursos.com.br/questoes/2114108","page":10,"prompt":"Toda vez que viaja ao interior, Luciano não vai à feira. Quando está em férias e não é dia útil, Luciano viaja ao interior. Se hoje Luciano foi à feira, então, necessariamente,","options":{"A":"é dia útil.","B":"Luciano está em férias.","C":"Luciano não está em férias.","D":"não é dia útil.","E":"Luciano não viajou ao interior."},"answer":"E","visualRequired":false},{"id":"tec-2163561","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - FRE (SEFAZ AP)/SEFAZ AP/2022","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":2163561,"url":"https://www.tecconcursos.com.br/questoes/2163561","page":11,"prompt":"I. Denise conhece Paris e não é maior de idade. II. Se Denise é maior de idade, então ela viaja sozinha. III. Denise viaja sozinha ou não conhece Paris, ou as duas coisas. Nessas condições, é necessariamente verdade que Denise","options":{"A":"é maior de idade e viaja sozinha.","B":"é maior de idade e não conhece Paris.","C":"não é maior de idade e conhece Paris.","D":"não viaja sozinha e conhece Paris.","E":"conhece Paris e não é maior de idade"},"answer":"B","visualRequired":false},{"id":"tec-2293579","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - AJ TRT5/TRT 5/Apoio Especializado/Tecnologia da Informação/2022","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":2293579,"url":"https://www.tecconcursos.com.br/questoes/2293579","page":11,"prompt":"Se Adão vai ao cinema, Benedito consegue estudar e Carla não faz brigadeiro. Carla fez brigadeiro, então podemos afirmar que","options":{"A":"Benedito conseguiu estudar.","B":"Adão não foi ao cinema.","C":"Benedito não conseguiu estudar.","D":"Adão foi ao cinema.","E":"Adão foi ao cinema se Benedito conseguiu estudar."},"answer":"B","visualRequired":false},{"id":"tec-1821202","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - ARE IV (SEF SC)/SEF SC/2021","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":1821202,"url":"https://www.tecconcursos.com.br/questoes/1821202","page":11,"prompt":"Das três afirmações a seguir, apenas uma é verdadeira. I. Se Pedro ama Júlia, então Bia vai mudar para a Espanha. II. Bia vai mudar para a Espanha ou virar cabeleireira, ou as duas coisas. III. Bia não vai virar cabeleireira e Pedro não ama Júlia. Nessas condições, é necessariamente verdade que","options":{"A":"Pedro ama Júlia e Bia vai mudar para a Espanha.","B":"Pedro ama Júlia e Bia vai virar cabeleireira.","C":"Pedro não ama Júlia e Bia vai mudar para a Espanha.","D":"Pedro não ama Júlia e Bia vai virar cabeleireira.","E":"Bia não vai mudar para a Espanha nem virar cabeleireira."},"answer":"B","visualRequired":false},{"id":"tec-1235178","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Ana Leg (ALAP)/ALAP/Atividade Administrativa/Administrador/2020","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":1235178,"url":"https://www.tecconcursos.com.br/questoes/1235178","page":11,"prompt":"Em um circo, todo trapezista é também malabarista. Sabendo que, nesse circo, se um artista é contorcionista e não é equilibrista, então ele não é malabarista, é correto concluir que se um artista é trapezista, então ele","options":{"A":"não é contorcionista nem equilibrista.","B":"não é malabarista.","C":"é equilibrista ou não é contorcionista.","D":"é equilibrista ou contorcionista.","E":"é malabarista e não é equilibrista."},"answer":"C","visualRequired":false},{"id":"tec-758799","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - AssGP (Pref Recife)/Pref Recife/2019","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":758799,"url":"https://www.tecconcursos.com.br/questoes/758799","page":11,"prompt":"Sempre que eu passo na frente da casa de Rosa, o cão late. Se o cão late, então o gato mia, o bebê chora e o guarda apita. Quando o bebê chora e a babá não está em casa, a mãe não dorme. Se a mãe dorme e a babá não está em casa, então","options":{"A":"não passo na casa de Rosa e o guarda não apita.","B":"o cão não late e o guarda não apita.","C":"não passo na casa de Rosa e o cão não late.","D":"passo na casa de Rosa e o gato não mia.","E":"o cão não late e o gato não mia."},"answer":"C","visualRequired":false},{"id":"tec-866978","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Ass TF (Pref Manaus)/Pref Manaus/\"Sem Área\"/2019","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":866978,"url":"https://www.tecconcursos.com.br/questoes/866978","page":12,"prompt":"Aos domingos, − como pizza no jantar ou não tomo açaí, − corro ou jogo futebol e − tomo açaí ou não corro. Se, no último domingo, não joguei futebol, então","options":{"A":"corri e não comi pizza no jantar.","B":"não corri e comi pizza no jantar.","C":"não comi pizza no jantar e não tomei açaí.","D":"não corri e não tomei açaí.","E":"corri e tomei açaí."},"answer":"E","visualRequired":false},{"id":"tec-881580","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Tec Faz (Pref Manaus)/Pref Manaus/2019","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":881580,"url":"https://www.tecconcursos.com.br/questoes/881580","page":12,"prompt":"Todo sábado, Sabrina − vai ao parque ou vai ao cinema, − acorda cedo ou não vai ao parque e − janta fora ou não vai ao cinema. Se, no último sábado, não jantou fora, então, é verdade que Sabrina","options":{"A":"acordou cedo e foi ao parque.","B":"foi ao parque e ao cinema.","C":"acordou cedo e foi ao cinema.","D":"não foi ao parque, nem ao cinema.","E":"não acordou cedo e não foi ao cinema."},"answer":"A","visualRequired":false},{"id":"tec-882120","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - ATTIFM (Pref Manaus)/Pref Manaus/Programador/2019","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":882120,"url":"https://www.tecconcursos.com.br/questoes/882120","page":12,"prompt":"João não viaja no feriado, caso Joana esteja na capital ou o time de João não jogue. Se João viajou no feriado, então","options":{"A":"Joana não estava na capital e o time de João jogou.","B":"Joana estava na capital ou o time de João não jogou.","C":"Joana não estava na capital e o time de João não jogou.","D":"Joana estava na capital e o time de João não jogou.","E":"Joana não estava na capital ou o time de João jogou."},"answer":"A","visualRequired":false},{"id":"tec-916789","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - AET (DETRAN SP)/DETRAN SP/2019","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":916789,"url":"https://www.tecconcursos.com.br/questoes/916789","page":12,"prompt":"Em uma festa, se Carlos está acompanhado ou está feliz, canta e dança. Se, na última festa em que esteve, não dançou, então Carlos, necessariamente,","options":{"A":"não estava acompanhado, mas estava feliz.","B":"estava acompanhado, mas não estava feliz.","C":"não estava acompanhado, nem feliz.","D":"não cantou.","E":"cantou."},"answer":"C","visualRequired":false},{"id":"tec-982471","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Ass Adm (SANASA)/SANASA/Call Center/2019","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":982471,"url":"https://www.tecconcursos.com.br/questoes/982471","page":12,"prompt":"Em uma equipe de futebol, sempre que André ou Bruno não jogam, o técnico escala Carlos para jogar, e Daniel sempre joga quando André joga. Se Carlos não jogou, então","options":{"A":"André jogou, mas Bruno não.","B":"Daniel jogou, mas Bruno não.","C":"André e Bruno não jogaram.","D":"Bruno jogou, mas Daniel não.","E":"Daniel e André jogaram."},"answer":"E","visualRequired":false},{"id":"tec-1009988","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Ag SegM (METRO SP)/METRO SP/2019","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":1009988,"url":"https://www.tecconcursos.com.br/questoes/1009988","page":13,"prompt":"O inspetor de uma escola percebeu uma porta quebrada e identificou, pelas imagens do sistema de segurança, que foi pelo menos um dentre 4 alunos o responsável pelo dano. Ele sabe que: − se Gustavo não teve participação, então Henrique teve; − entre Henrique e Igor, exatamente um teve participação; − João teve participação se, e somente se, Igor teve participação. Para não prejudicar seus amigos, João, falando a verdade, assumiu ter participação, o que permite concluir que todos os responsáveis pelo dano foram","options":{"A":"João e Gustavo.","B":"João e Henrique.","C":"João e Igor.","D":"João, Gustavo e Igor.","E":"João, Gustavo e Henrique."},"answer":"D","visualRequired":false},{"id":"tec-1269037","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Ag Prev (RP Prev)/Rio Preto Prev/2019","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":1269037,"url":"https://www.tecconcursos.com.br/questoes/1269037","page":13,"prompt":"Se estou inspirado, escrevo um poema em 10 minutos. Se escrevo um poema em 10 minutos, então é inverno. Eu só escrevo poemas no verão ou no inverno. Meu último poema foi escrito no verão, o que permite concluir, logicamente, que, ao escrever meu último poema, eu","options":{"A":"estava inspirado.","B":"não estava inspirado.","C":"o escrevi em 10 minutos.","D":"o escrevi em mais de 10 minutos.","E":"estava inspirado ou o escrevi em menos de 10 minutos."},"answer":"B","visualRequired":false},{"id":"tec-618155","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - AJ TRT6/TRT 6/Administrativa/\"Sem Especialidade\"/2018","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":618155,"url":"https://www.tecconcursos.com.br/questoes/618155","page":13,"prompt":"Considere a afirmação I como sendo FALSA e as outras três afirmações como sendo VERDADEIRAS. I. Lucas é médico ou Marina não é enfermeira. II. Se Arnaldo é advogado, então Lucas não é médico. III. Ou Otávio é engenheiro, ou Marina é enfermeira, mas não ambos. IV. Lucas é médico ou Paulo é arquiteto. A partir dessas informações, é correto afirmar que","options":{"A":"Paulo não é arquiteto ou Marina não é enfermeira.","B":"Marina é enfermeira e Arnaldo não é advogado.","C":"Se Lucas não é médico, então Otávio é engenheiro.","D":"Otávio é engenheiro e Paulo não é arquiteto.","E":"Arnaldo é advogado ou Paulo é arquiteto."},"answer":"E","visualRequired":false},{"id":"tec-618780","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - TJ TRT6/TRT 6/Administrativa/Agente da Policia Judicial/2018","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":618780,"url":"https://www.tecconcursos.com.br/questoes/618780","page":13,"prompt":"Considere que a afirmação I é falsa e que as demais são verdadeiras. I. Se Bernardo é músico, então Andreia é cantora. II. Cátia é baterista e Bernardo é músico. III. Ou Danilo é violonista, ou Cátia é baterista. A partir dessas afirmações, é correto concluir que","options":{"A":"Andreia é cantora ou Danilo é violonista.","B":"ou Bernardo é músico, ou Cátia é baterista.","C":"se Danilo é violonista, então Andreia é cantora.","D":"Cátia é baterista e Danilo é violonista.","E":"se Cátia é baterista, então Danilo é violonista."},"answer":"C","visualRequired":false},{"id":"tec-623468","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Of Log Al (METRO SP)/METRO SP/I (ingresso)/2018","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":623468,"url":"https://www.tecconcursos.com.br/questoes/623468","page":13,"prompt":"Considere as afirmações: I. Se Enzo é engenheiro, então Fábio é farmacêutico. II. Carlos é contador ou Daniel é dentista. III. Antônio é artista ou Bruno é biblioteconomista. IV. Se Daniel é dentista então Antônio é artista. Sabe-se que as afirmações II e III são verdadeiras e que as demais são afirmações falsas. A partir dessas afirmações é correto concluir que","options":{"A":"Antônio é artista e Daniel é dentista.","B":"Carlos é contador ou Antônio é artista.","C":"Bruno é biblioteconomista e Enzo não é engenheiro.","D":"Enzo é engenheiro e Carlos é contador.","E":"Bruno é biblioteconomista ou Fábio é farmacêutico."},"answer":"E","visualRequired":false},{"id":"tec-638536","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Estag (SABESP)/SABESP/Ensino Médio Técnico/2018","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":638536,"url":"https://www.tecconcursos.com.br/questoes/638536","page":14,"prompt":"Considere as afirmações: I. Carlos é engenheiro e Marina é analista. II. Se Pedro é administrador, então Marina não é analista. III. Alberto é médico ou advogado. IV. Se Alberto é advogado, então Pedro é administrador. V. Alberto não é médico. Sabendo que a afirmação I é falsa e as demais são afirmações verdadeiras, é correto concluir a partir das afirmações que","options":{"A":"Pedro é administrador.","B":"Alberto não é advogado.","C":"Pedro não é administrador.","D":"Marina é analista.","E":"Carlos é engenheiro."},"answer":"A","visualRequired":false},{"id":"tec-644443","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Adv (SABESP)/SABESP/2018","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":644443,"url":"https://www.tecconcursos.com.br/questoes/644443","page":14,"prompt":"A respeito de um objeto, sabe-se que: − se é pequeno, então é escuro; − se é quadrado, então é de papel; − se não é pequeno, então não é quadrado. Se o objeto é quadrado, é correto afirmar que ele é","options":{"A":"pequeno, escuro, mas não é de papel.","B":"pequeno, claro e de papel.","C":"de papel, escuro e grande.","D":"de papel, escuro e pequeno.","E":"grande, escuro e de papel."},"answer":"D","visualRequired":false},{"id":"tec-654965","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Ana Exec (SEGEP MA)/SEGEP MA/Contador/2018","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":654965,"url":"https://www.tecconcursos.com.br/questoes/654965","page":14,"prompt":"Considere as seguintes sentenças: Se Cláudio candidatou-se ao cargo, então Bruno também se candidatou. Se Bruno candidatou-se ao cargo, então Alice também se candidatou. Sabe-se que Bruno não se candidatou ao cargo. Considere as sentenças abaixo. I. Cláudio candidatou-se ao cargo. II. Alice não se candidatou ao cargo. III. Cláudio não se candidatou ao cargo. É necessariamente verdadeiro o que se afirma APENAS em","options":{"A":"I.","B":"II.","C":"III.","D":"I e II.","E":"II e III."},"answer":"C","visualRequired":false},{"id":"tec-664593","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - AJ TRT15/TRT 15/Judiciária/Oficial de Justiça Avaliador Federal/2018","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":664593,"url":"https://www.tecconcursos.com.br/questoes/664593","page":15,"prompt":"A, B, C e D são alguns dos candidatos à presidência de um certo país. Um analista político, em entrevista a um programa de rádio, fez três previsões sobre o 1º turno das eleições: − Se A ficar em primeiro lugar, então nem B e nem C ficarão entre os três primeiros. − Se B ficar entre os três primeiros, então A não ficará entre os três primeiros. − Se D ficar entre os três primeiros, então C ficará entre os três primeiros. Assim, se A ficar em primeiro lugar no 1o turno e se as previsões do analista estiverem corretas, então, sobre B, C e D, pode-se concluir que","options":{"A":"certamente nenhum deles estará entre os três primeiros.","B":"D poderá ou não estar entre os três primeiros.","C":"certamente apenas D estará entre os três primeiros.","D":"C ou D, mas não ambos, poderão estar entre os três primeiros.","E":"certamente apenas B e C não estarão entre os três primeiros."},"answer":"A","visualRequired":false},{"id":"tec-665004","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - AJ TRT15/TRT 15/Administrativa/Sem Especialidade/2018","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":665004,"url":"https://www.tecconcursos.com.br/questoes/665004","page":15,"prompt":"Considere os dois argumentos a seguir: I. Se Ana Maria nunca escreve petições, então ela não sabe escrever petições. Ana Maria nunca escreve petições. Portanto, Ana Maria não sabe escrever petições. II. Se Ana Maria não sabe escrever petições, então ela nunca escreve petições. Ana Maria nunca escreve petições. Portanto, Ana Maria não sabe escrever petições. Comparando a validade formal dos dois argumentos e a plausibilidade das primeiras premissas de cada um, é correto concluir que","options":{"A":"o argumento I é inválido e o argumento II é válido, mesmo que a primeira premissa de I seja mais plausível que a de II.","B":"ambos os argumentos são válidos, a despeito das primeiras premissas de ambos serem ou não plausíveis.","C":"ambos os argumentos são inválidos, a despeito das primeiras premissas de ambos serem ou não plausíveis.","D":"o argumento I é inválido e o argumento II é válido, pois a primeira premissa de II é mais plausível que a de I.","E":"o argumento I é válido e o argumento II é inválido, mesmo que a primeira premissa de II seja mais plausível que a de I."},"answer":"E","visualRequired":false},{"id":"tec-674604","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - APE (TCE-RS)/TCE RS/Ciências Jurídicas e Sociais, Direito/2018","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":674604,"url":"https://www.tecconcursos.com.br/questoes/674604","page":15,"prompt":"No ano passado, Marcelo prometeu que se o seu time ganhasse todos os jogos e seu ídolo Canelinha fosse o artilheiro do campeonato, então ele ficaria todo o ano seguinte sem tomar cerveja. Sabendo que Marcelo cumpre todas as suas promessas e que, neste ano, ele tem tomado cerveja todo final de semana, é correto concluir que, no ano passado, necessariamente,","options":{"A":"o time de Marcelo perdeu ou empatou pelo menos um jogo.","B":"pelo menos um jogador marcou mais gols do que Canelinha no campeonato.","C":"o time de Marcelo perdeu todos os jogos e Canelinha não foi o artilheiro do campeonato.","D":"o time de Marcelo não ganhou todos os jogos ou Canelinha não marcou gols no campeonato.","E":"o time de Marcelo não ganhou todos os jogos ou Canelinha não foi o artilheiro do campeonato."},"answer":"E","visualRequired":false},{"id":"tec-686711","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - AJ TRT2/TRT 2/Apoio Especializado/Serviço Social/2018","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":686711,"url":"https://www.tecconcursos.com.br/questoes/686711","page":15,"prompt":"Considere as seguintes afirmações: I. Agnes é atriz ou Bernardo não é diretor. II. Cíntia é estilista e Dinorá não é cantora. III. Elivaldo não é segurança ou Fred é assistente. IV. Se Bernardo é diretor, então Elivaldo não é segurança. Sabe-se que as afirmações I e IV são falsas e que as afirmações II e III são verdadeiras. Sendo assim, é logicamente VERDADEIRA a alternativa","options":{"A":"Dinorá é cantora ou Agnes é atriz.","B":"Se Agnes é atriz, então Elivaldo é segurança.","C":"Fred não é assistente e Cíntia é estilista.","D":"Se Bernardo é diretor, então Dinorá é cantora.","E":"Ou Bernardo não é diretor ou Fred não é assistente."},"answer":"B","visualRequired":false},{"id":"tec-718963","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - AFRE (SEF SC)/SEF SC/Auditoria e Fiscalização/2018","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":718963,"url":"https://www.tecconcursos.com.br/questoes/718963","page":15,"prompt":"Considere as seguintes premissas: − Se eu vou para a academia, eu durmo bem. − Eu durmo bem e me alimento bem. − Eu me alimento bem ou trabalho o dia inteiro. A partir dessas premissas, uma conclusão válida é","options":{"A":"“eu trabalho o dia inteiro e me alimento bem”.","B":"“se eu trabalho o dia inteiro, eu durmo bem”.","C":"“eu vou para a academia e durmo bem”.","D":"“se eu vou para a academia, eu trabalho o dia inteiro”.","E":"“eu vou para a academia ou trabalho o dia inteiro”."},"answer":"B","visualRequired":false},{"id":"tec-718969","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - AFRE (SEF SC)/SEF SC/Auditoria e Fiscalização/2018","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":718969,"url":"https://www.tecconcursos.com.br/questoes/718969","page":16,"prompt":"Em certo país A, a proposição “ se um político comete um ato de corrupção, então ele é preso” é verdadeira. Em outro país B, é verdadeira a proposição “ se um político está preso, então ele cometeu um ato de corrupção”. Com base apenas nessas informações, pode-se concluir que,","options":{"A":"no país A, todo político preso cometeu um ato de corrupção.","B":"em ambos os países, podem existir políticos presos que não cometeram um ato de corrupção.","C":"no país B, podem existir políticos que cometeram atos de corrupção e não estão presos.","D":"em ambos os países, podem existir políticos que cometeram atos de corrupção e não estão presos.","E":"no país B, se um político está livre, ele não cometeu um ato de corrupção."},"answer":"C","visualRequired":false},{"id":"tec-734711","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Ass Adm (SEAD AP)/SEAD AP/2018","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":734711,"url":"https://www.tecconcursos.com.br/questoes/734711","page":16,"prompt":"Todo domingo, se não chove, Fernanda passeia. Se não é domingo ou faz frio, Vanessa não usa sua bicicleta. Sempre que chove, André leva consigo um guarda- chuva. Assim, se Vanessa usa sua bicicleta e André não leva consigo um guarda-chuva,","options":{"A":"é domingo e faz frio.","B":"é domingo e chove.","C":"faz frio e Fernanda passeia.","D":"não chove e Fernanda não passeia.","E":"não faz frio e Fernanda passeia."},"answer":"E","visualRequired":false},{"id":"tec-780364","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Edu SP (IAPEN AP)/IAPEN AP/Nível Médio/2018","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":780364,"url":"https://www.tecconcursos.com.br/questoes/780364","page":16,"prompt":"Considere verdadeiras as afirmações: − Estudo ou passeio. − Vou à escola ou não estudo. − Fico em casa ou não passeio. Ontem não fiquei em casa, portanto,","options":{"A":"passeei e estudei.","B":"não passeei e não estudei.","C":"fui à escola e estudei.","D":"estudei e não fui à escola.","E":"não passeei e não fui à escola."},"answer":"C","visualRequired":false},{"id":"tec-988405","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Vest (IBMEC)/IBMEC/Administração/2018","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":988405,"url":"https://www.tecconcursos.com.br/questoes/988405","page":16,"prompt":"Considere a seguinte sentença: “Se Teobaldo estudou toda a matéria da prova, e se ele não estiver doente, então ele fará uma boa prova”. Assim, sabendo que Teobaldo foi mal na prova, conclui-se que","options":{"A":"ele ficou doente no dia da prova.","B":"ele não estudou toda a matéria da prova.","C":"ele não estudou toda a matéria da prova, ou ele estava doente.","D":"ele estudou apenas uma parte da matéria da prova.","E":"ele ficou doente e, por isso, não conseguiu estudar toda a matéria da prova."},"answer":"C","visualRequired":false},{"id":"tec-445248","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Estag (SABESP)/SABESP/Ensino Médio Regular/2017","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":445248,"url":"https://www.tecconcursos.com.br/questoes/445248","page":16,"prompt":"Em uma festa de aniversário serão servidos alfajores, brigadeiros e cajuzinhos. Sabe-se que ou os alfajores serão servidos primeiro ou os brigadeiros serão servidos por último. Sabe-se também que ou os brigadeiros serão servidos primeiro ou os cajuzinhos serão servidos primeiro. Serão servidos os doces nessa festa na seguinte ordem:","options":{"A":"os alfajores, os brigadeiros e os cajuzinhos.","B":"os cajuzinhos, os alfajores e os brigadeiros.","C":"os alfajores, os cajuzinhos e os brigadeiros.","D":"os brigadeiros, os alfajores e os cajuzinhos.","E":"os cajuzinhos, os brigadeiros e os alfajores."},"answer":"B","visualRequired":false},{"id":"tec-445475","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Estag (SABESP)/SABESP/Ensino Superior/2017","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":445475,"url":"https://www.tecconcursos.com.br/questoes/445475","page":17,"prompt":"As amigas Arlete, Bárbara e Camila gostam de usar capinhas amarelas ou vermelhas em seus telefones celulares. Considere as seguintes afirmativas. − Se Arlete usa uma capinha da mesma cor que Camila, então Bárbara usa uma capinha amarela. − Se Arlete usa uma capinha de cor diferente da de Bárbara, então Camila usa uma capinha vermelha. − Se Bárbara usa uma capinha de cor diferente da de Camila, então Arlete usa uma capinha amarela. Está correto afirmar que","options":{"A":"Bárbara sempre usa uma capinha vermelha.","B":"Bárbara sempre usa uma capinha amarela.","C":"Camila sempre usa uma capinha vermelha.","D":"Arlete sempre usa uma capinha amarela.","E":"Arlete sempre usa uma capinha vermelha."},"answer":"D","visualRequired":false},{"id":"tec-585170","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - TJ TST/TST/Administrativa/Agente da Policia Judicial/2017","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":585170,"url":"https://www.tecconcursos.com.br/questoes/585170","page":17,"prompt":"Foi realizada uma pesquisa junto aos clientes de um determinado shopping center. As afirmações abaixo foram recolhidas a partir da fala de alguns desses clientes: I. Quando os preços são altos, as lojas têm boa reputação. II. Sempre que os produtos são de boa qualidade, os preços são altos. III. Há lojas com produtos de boa qualidade, mas com atendimento ruim. IV. Sempre que as lojas são bem decoradas, elas têm bom atendimento. V. As lojas com boa reputação são sempre bem decoradas. A afirmação que está em contradição com o conjunto das demais é a","options":{"A":"I.","B":"V.","C":"III.","D":"IV.","E":"II."},"answer":"C","visualRequired":false},{"id":"tec-358384","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - AJ TRF3/TRF 3/Administrativa/2016","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":358384,"url":"https://www.tecconcursos.com.br/questoes/358384","page":17,"prompt":"Considere verdadeiras as afirmações abaixo. I. Ou Bruno é médico, ou Carlos não é engenheiro. II. Se Durval é administrador, então Eliane não é secretária. III. Se Bruno é médico, então Eliane é secretária. IV. Carlos é engenheiro. A partir dessas afirmações, pode-se concluir corretamente que","options":{"A":"Eliane não é secretária e Durval não é administrador.","B":"Bruno não é médico ou Durval é administrador.","C":"se Eliane não é secretária, então Bruno não é médico.","D":"Carlos é engenheiro e Eliane não é secretária.","E":"se Carlos é engenheiro, então Eliane não é secretária."},"answer":"C","visualRequired":false},{"id":"tec-358392","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - AJ TRF3/TRF 3/Administrativa/2016","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":358392,"url":"https://www.tecconcursos.com.br/questoes/358392","page":17,"prompt":"Considere, abaixo, as afirmações e o valor lógico atribuído a cada uma delas entre parênteses. − Ou Júlio é pintor, ou Bruno não é cozinheiro (afirmação FALSA). − Se Carlos é marceneiro, então Júlio não é pintor (afirmação FALSA). − Bruno é cozinheiro ou Antônio não é pedreiro (afirmação VERDADEIRA). A partir dessas afirmações,","options":{"A":"Júlio não é pintor e Bruno não é cozinheiro.","B":"Antônio é pedreiro ou Bruno é cozinheiro.","C":"Carlos é marceneiro e Antônio não é pedreiro.","D":"Júlio é pintor e Carlos não é marceneiro.","E":"Antônio é pedreiro ou Júlio não é pintor."},"answer":"C","visualRequired":false},{"id":"tec-369478","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - PMO (ELETROSUL)/ELETROSUL/Técnico de Segurança do Trabalho/2016","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":369478,"url":"https://www.tecconcursos.com.br/questoes/369478","page":18,"prompt":"Considere as seguintes afirmações: I. Se a temperatura está baixa, então a minha pele está seca. II. Se não tenho rachaduras nas mãos, então a minha pele não está seca. III. Se eu tenho rachaduras nas mãos, então eu sinto dor nas mãos. IV. Não sinto dor nas mãos. A partir delas é correto concluir que","options":{"A":"é possível ter dor nas mãos causada por outro motivo.","B":"não tenho rachaduras nas mãos ou a temperatura está baixa.","C":"minha pele não está seca e tenho rachaduras nas mãos.","D":"não tenho rachaduras nas mãos e a temperatura está baixa.","E":"tenho rachaduras nas mãos ou a temperatura está baixa."},"answer":"B","visualRequired":false},{"id":"tec-375363","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Eng (COPERGÁS)/COPERGÁS/Civil/2016","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":375363,"url":"https://www.tecconcursos.com.br/questoes/375363","page":18,"prompt":"Se Maria é economista, então Jorge é contador. Se Luiza é administradora, então Jorge não é contador. Se Luiza não é administradora, então Norberto é engenheiro. Sabe-se que Norberto não é engenheiro. A partir dessas informações é possível concluir corretamente que","options":{"A":"Luiza é administradora ou Maria é economista.","B":"Maria é economista ou Jorge é contador.","C":"Jorge é contador e Norberto não é engenheiro.","D":"Maria não é economista e Luiza não é administradora.","E":"Jorge não é contador e Luiza não é administradora."},"answer":"A","visualRequired":false},{"id":"tec-375880","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Tec Op (COPERGÁS)/COPERGÁS/Mecânico/2016","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":375880,"url":"https://www.tecconcursos.com.br/questoes/375880","page":18,"prompt":"Considere verdadeiras as afirmações a seguir: I. Laura é economista ou João é contador. II. Se Dinorá é programadora, então João não é contador. III. Beatriz é digitadora ou Roberto é engenheiro. IV. Roberto é engenheiro e Laura não é economista. A partir dessas informações é possível concluir, corretamente, que","options":{"A":"Beatriz é digitadora.","B":"João é contador.","C":"Dinorá é programadora.","D":"Beatriz não é digitadora.","E":"João não é contador."},"answer":"B","visualRequired":false},{"id":"tec-400514","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - TRE (SEFAZ MA)/SEFAZ MA/Arrecadação e Fiscalização de Mercadorias em Trânsito/2016","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":400514,"url":"https://www.tecconcursos.com.br/questoes/400514","page":18,"prompt":"Se Roberta for promovida, então Antônio não será demitido. Se Cláudia se aposentar, então Douglas não perderá o seu posto. Se Douglas não perder seu posto, então Antônio será demitido. Sabe-se que Cláudia se aposentou. A partir dessas informações é correto concluir que","options":{"A":"Antônio não será demitido ou Roberta será promovida.","B":"Roberta não foi promovida ou Cláudia não se aposentou.","C":"Douglas perdeu seu posto e Antônio não será demitido.","D":"se Douglas não perder seu posto, então Cláudia não irá se aposentar.","E":"Roberta foi promovida e Douglas não perdeu seu posto."},"answer":"B","visualRequired":false},{"id":"tec-410321","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - TNS (Pref Teresina)/Pref Teresina/Administrador/2016","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":410321,"url":"https://www.tecconcursos.com.br/questoes/410321","page":19,"prompt":"Considere as seguintes afirmações. I. Se Adalberto não é estudioso, então Bruno é esforçado. II. Se Daniela é atenta, então Ernesto não é assíduo. III. Se Bruno é esforçado, então Cátia é organizada. IV. Se Ernesto é assíduo, então Fátima é pontual. V. Se Fátima é pontual, então Cátia é organizada. VI. Cátia não é organizada. A partir dessas afirmações, é correto concluir que","options":{"A":"Adalberto não é estudioso e Bruno é esforçado.","B":"Daniela é atenta ou Fátima é pontual.","C":"Adalberto é estudioso ou Daniela não é atenta.","D":"Ernesto não é assíduo e Adalberto não é estudioso.","E":"Bruno é esforçado ou Fátima é pontual."},"answer":"C","visualRequired":false},{"id":"tec-410515","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - ALegis (ALMS)/ALMS/Administrador/2016","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":410515,"url":"https://www.tecconcursos.com.br/questoes/410515","page":19,"prompt":"Considere as afirmações e seus respectivos valores lógicos. I. André não é analista ou Bruno é biblioteconomista. Afirmação VERDADEIRA. II. Se Carlos não é cerimonialista, então Dorival é contador. Afirmação FALSA. III. André não é analista e Dorival não é contador. Afirmação FALSA. IV. Se Bruno é biblioteconomista, então Ernani é economista. Afirmação VERDADEIRA. A partir dessas afirmações, é correto concluir que","options":{"A":"Se Ernani é economista, então André não é analista.","B":"Carlos não é cerimonialista e Bruno não é biblioteconomista.","C":"Carlos é cerimonialista e Ernani é economista.","D":"André não é analista ou Dorival é contador.","E":"Bruno não é biblioteconomista ou Dorival não é contador"},"answer":"E","visualRequired":false},{"id":"tec-426189","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Moto (CREMESP)/CREMESP/2016","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":426189,"url":"https://www.tecconcursos.com.br/questoes/426189","page":19,"prompt":"Considere as afirmações: I. Se chove, então o nível do rio sobe. II. Se o nível do rio sobe, então não dá para pescar. III. Sempre que acontecem quatro dias seguidos de sol, no dia seguinte chove. IV. Hoje é o quarto dia seguido de sol. A partir dessas afirmações, é correto concluir que amanhã","options":{"A":"não vai chover.","B":"vai chover e dará para pescar.","C":"mesmo chovendo, o nível do rio não subirá.","D":"não choverá e mesmo assim o nível do rio subirá.","E":"não dará para pescar."},"answer":"E","visualRequired":false},{"id":"tec-426244","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Op CC (CREMESP)/CREMESP/2016","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":426244,"url":"https://www.tecconcursos.com.br/questoes/426244","page":19,"prompt":"Considere verdadeiras as afirmações abaixo: I. Se Alice vai ao teatro, então Beto também vai ao teatro. II. Se Beto vai ao teatro, então Carolina também vai ao teatro. III. Beto não foi ao teatro. Nesse caso, dentre as afirmações a seguir, a única necessariamente correta é:","options":{"A":"Nem Alice e nem Carolina foram ao teatro.","B":"Alice foi ao teatro, mas Carolina não foi.","C":"Carolina não foi ao teatro.","D":"Carolina foi ao teatro, mas Alice não foi.","E":"Alice não foi ao teatro."},"answer":"E","visualRequired":false},{"id":"tec-428579","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Adv Jr (METRO SP)/METRO SP/2016","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":428579,"url":"https://www.tecconcursos.com.br/questoes/428579","page":20,"prompt":"Considere as afirmações verdadeiras: I. Se chove, então o nível do rio sobe. II. Se o nível do rio não sobe, então dá para pescar. III. Se o nível do rio sobe, então dá para saltar da ponte. IV. Não deu para saltar da ponte. A partir dessas afirmações é correto concluir que","options":{"A":"o nível do rio subiu.","B":"não saltei da ponte porque é perigoso.","C":"não choveu e o nível do rio subiu.","D":"deu para pescar.","E":"choveu."},"answer":"D","visualRequired":false},{"id":"tec-429009","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Aux Enf T (METRO SP)/METRO SP/2016","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":429009,"url":"https://www.tecconcursos.com.br/questoes/429009","page":20,"prompt":"Considere verdadeiras as afirmações: I. Se o relógio toca, então abro os olhos. II. Se ainda está escuro, me demoro para levantar. III. Se não saio de casa no horário certo, me atraso para o trabalho. IV. Não abro os olhos e ainda está escuro. A partir dessas afirmações, é correto concluir que","options":{"A":"me atraso para o trabalho.","B":"me levanto correndo.","C":"o relógio não toca.","D":"saio de casa no horário certo.","E":"não me atraso para o trabalho."},"answer":"C","visualRequired":false},{"id":"tec-621411","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Ass Adm (SANASA)/SANASA/2016","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":621411,"url":"https://www.tecconcursos.com.br/questoes/621411","page":20,"prompt":"Sabe-se que toda água potável é água doce. Provei a água que estava no pote de barro, é água doce. Provei a água que estava no pote de alumínio, é água salgada. Do ponto de vista da lógica formal, a partir dessas afirmações é correto dizer que o pote de","options":{"A":"barro contém água potável.","B":"barro contém água potável e o pote de alumínio não.","C":"alumínio contém água doce ou contém água salgada.","D":"alumínio não contém água salgada ou contém água potável.","E":"barro não contém água potável."},"answer":"C","visualRequired":false},{"id":"tec-621667","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Ag Mec MA (SANASA)/SANASA/Motor Diesel/2016","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":621667,"url":"https://www.tecconcursos.com.br/questoes/621667","page":20,"prompt":"Se faltar água, então fico com sede. Se fico com sede, então o meu humor piora. O meu humor não piorou. Sendo assim, é correto concluir que","options":{"A":"a água não faltou e eu não fiquei com sede.","B":"fiquei com sede mas me controlei.","C":"não fiquei com sede, mas a água tinha faltado.","D":"a água não faltou, mas eu fiquei com sede.","E":"a água não faltou e o meu humor piorou."},"answer":"A","visualRequired":false},{"id":"tec-256383","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - ATE (SEFAZ PI)/SEFAZ PI/2015","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":256383,"url":"https://www.tecconcursos.com.br/questoes/256383","page":21,"prompt":"As afirmações a seguir, todas verdadeiras, foram feitas pelo chefe do departamento de Imunologia de uma faculdade de medicina, referindo-se a eventos que poderiam acontecer no ano de 2014. 1. Se o projeto for aprovado, o departamento receberá novos computadores e terá seu laboratório reformado. 2 . Se o laboratório for reformado, passará a ter capacidade para processar o sangue de 50 pacientes por dia. 3. Se for possível processar o sangue de 50 pacientes por dia, o número de atendimentos diários no ambulatório será duplicado. A partir dessas informações, é correto concluir que, se a capacidade de processamento de sangue do laboratório do departamento de Imunologia, em 2015, é de apenas 25 pacientes por dia, então, necessariamente,","options":{"A":"o departamento não recebeu novos computadores.","B":"o número de atendimentos diários no ambulatório não foi duplicado.","C":"o laboratório do departamento foi reformado.","D":"o projeto citado pelo chefe do departamento não foi aprovado.","E":"a capacidade de processamento de sangue do laboratório manteve-se constante."},"answer":"D","visualRequired":false},{"id":"tec-272757","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - AP (MANAUSPREV)/MANAUSPREV/Administrativa/2015","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":272757,"url":"https://www.tecconcursos.com.br/questoes/272757","page":21,"prompt":"Considere as afirmações sobre Alberto, Bruno, César e Dario sendo que cada um toca apenas um instrumento. I. Alberto é pianista ou Bruno é saxofonista. II. Bruno é saxofonista ou César é violinista. III. Se César é violinista, então Dario é clarinetista. Dentre essas afirmações, sabe-se que são verdadeiras I e III e que a II é falsa. Deste modo,","options":{"A":"Bruno não é saxofonista e Dario não é clarinetista.","B":"Se César não é violinista, então Bruno é saxofonista.","C":"Dario é clarinetista e Bruno é saxofonista.","D":"Se Dario é clarinetista, então Alberto não é pianista.","E":"César é violinista ou Alberto é pianista."},"answer":"E","visualRequired":false},{"id":"tec-280203","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Ag SegM (METRO SP)/METRO SP/2015","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":280203,"url":"https://www.tecconcursos.com.br/questoes/280203","page":21,"prompt":"Considere as afirmações verdadeiras: − Se Lúcia chegar antes de soar o sinal das portas, então ela entra no metrô. − Se Lúcia entra no metrô, então ela chega ao trabalho na hora certa. − Se Lúcia corre, então ela chega antes de soar o sinal das portas do metrô. − Lúcia correu. A partir dessas afirmações é possível concluir corretamente que","options":{"A":"Lúcia entrou no metrô e não chegou ao trabalho na hora certa.","B":"Lúcia correu, mas não o suficiente, ou desistiu de chegar ao trabalho na hora certa.","C":"Lúcia não entrou no metrô e não chegou ao trabalho na hora certa.","D":"Lúcia chegou antes de soar o sinal das portas e não entrou no metrô.","E":"Lúcia chegou ao trabalho na hora certa ou Lúcia correu."},"answer":"E","visualRequired":false},{"id":"tec-283222","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - TCE (TCE-CE)/TCE CE/Controle Externo/Auditoria de Tecnologia da Informação/2015","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":283222,"url":"https://www.tecconcursos.com.br/questoes/283222","page":21,"prompt":"Considere as afirmações verdadeiras: − Se compro leite ou farinha, então faço um bolo. − Se compro ovos e frango, então faço uma torta. − Comprei leite e não comprei ovos. − Comprei frango ou não comprei farinha. − Não comprei farinha. A partir dessas afirmações, é correto concluir que","options":{"A":"fiz uma torta.","B":"não fiz uma torta e não fiz um bolo.","C":"fiz um bolo.","D":"nada comprei.","E":"comprei apenas leite e ovos."},"answer":"C","visualRequired":false},{"id":"tec-283227","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - TCE (TCE-CE)/TCE CE/Controle Externo/Auditoria de Tecnologia da Informação/2015","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":283227,"url":"https://www.tecconcursos.com.br/questoes/283227","page":22,"prompt":"Considere as afirmações: I. Se a música toca no rádio, então você escuta. II. A música não tocou no rádio. III. Renato é bom em matemática ou é bom em português. IV. Se as nuvens estão escuras, então vai chover. Sabe-se que as afirmações I e II são verdadeiras, e as afirmações III e IV são falsas. A partir dessas afirmações, é correto concluir que","options":{"A":"Você escutou a música, e Renato não é bom em matemática, e não é bom em português.","B":"A música não tocou no rádio, e as nuvens não estão escuras, e vai chover.","C":"Você escutou a música, e Renato é bom somente em matemática, e está chovendo.","D":"A música não tocou no rádio, e Renato não é bom em português, e as nuvens estão escuras.","E":"A música não tocou no rádio, e Renato não é bom em matemática, e é bom em português, e não vai chover."},"answer":"D","visualRequired":false},{"id":"tec-323471","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Adm (DPE RR)/DPE RR/2015","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":323471,"url":"https://www.tecconcursos.com.br/questoes/323471","page":22,"prompt":"Alberto, Bernardo e Carlos estão planejando ir a uma festa. Se Alberto for a festa, então Bernardo também irá. Se Bernardo não for a festa, então Carlos também não irá. De acordo com isso, é necessariamente correto afirmar que:","options":{"A":"Se Carlos for a festa, então Bernardo também irá à festa.","B":"Se Alberto for a festa, então Carlos também irá à festa.","C":"Se Alberto não for a festa, então Bernardo também não irá à festa.","D":"Se Alberto não for a festa, então Bernardo irá à festa.","E":"Se Carlos for a festa, então Bernardo não irá à festa."},"answer":"A","visualRequired":false},{"id":"tec-323473","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Adm (DPE RR)/DPE RR/2015","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":323473,"url":"https://www.tecconcursos.com.br/questoes/323473","page":22,"prompt":"Se Daniela possui pelo menos três carros, então Elisa possui três carros. Se Elisa possui carro, então Fernanda possui cinco carros. Sabendo-se que Daniela possui cinco carros, foram feitas as seguintes afirmações: I. Elisa possui carro; II. Fernanda possui carro; III. Fernanda não possui carro. Das três afirmações feitas, são necessariamente corretas APENAS","options":{"A":"I.","B":"II.","C":"III.","D":"I e II.","E":"I e III."},"answer":"D","visualRequired":false},{"id":"tec-325597","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Aux Adm (DPE RR)/DPE RR/2015","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":325597,"url":"https://www.tecconcursos.com.br/questoes/325597","page":22,"prompt":"Considere as afirmações: Se Janete sair mais cedo, então Clara ficará trabalhando até mais tarde. Se Dalva não for trabalhar, então Janete sairá mais cedo. Dalva não foi trabalhar. A partir das afirmações é correto concluir que","options":{"A":"Clara ficou trabalhando até mais tarde.","B":"Janete não foi trabalhar.","C":"Dalva foi trabalhar.","D":"Janete não saiu mais cedo.","E":"Clara não foi trabalhar."},"answer":"A","visualRequired":false},{"id":"tec-326002","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Aux Tec Fis (TCE-SP)/TCE SP/\"Sem Área\"/2015","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":326002,"url":"https://www.tecconcursos.com.br/questoes/326002","page":23,"prompt":"Considere verdadeiras as afirmações: − Daniel não bebe cerveja. − Se André prefere doces, então Bernardo bebe água. − Se Caio gosta de feijoada, então Daniel bebe cerveja. − Bernardo bebe água ou Caio gosta de feijoada. A partir dessas afirmações é possível concluir, corretamente, que","options":{"A":"Caio gosta de feijoada e Bernardo bebe água.","B":"André prefere doces e Daniel não bebe cerveja.","C":"Caio não gosta de feijoada ou André prefere doces.","D":"Caio não gosta de feijoada e Daniel bebe cerveja.","E":"Bernardo não bebe água ou André não prefere doces."},"answer":"C","visualRequired":false},{"id":"tec-170522","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - TJ TRT2/TRT 2/Apoio Especializado/Enfermagem/2014","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":170522,"url":"https://www.tecconcursos.com.br/questoes/170522","page":23,"prompt":"Cinco irmãs, discutindo sobre a festa que aconteceria na cidade no final do mês, fizeram as afirmações abaixo. − Se a Paula for à festa, então a Bruna também irá. − Se a Renata não for à festa, então a Laura irá. − Se a Flávia não for à festa, então a Bruna também não irá. − Se a Laura for à festa, então a Paula também irá. Sabendo que as quatro afirmações são verdadeiras e que Paula não foi à festa, pode-se concluir que, necessariamente,","options":{"A":"Bruna não foi à festa.","B":"Flávia não foi à festa.","C":"Flávia foi à festa.","D":"Renata não foi à festa.","E":"Renata foi à festa."},"answer":"E","visualRequired":false},{"id":"tec-170822","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - AJ TRT2/TRT 2/Judiciária/Oficial de Justiça Avaliador Federal/2014","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":170822,"url":"https://www.tecconcursos.com.br/questoes/170822","page":23,"prompt":"Considere as três afirmações a seguir, todas verdadeiras, feitas em janeiro de 2013. I. Se o projeto X for aprovado até maio de 2013, então um químico e um biólogo serão contratados em junho do mesmo ano. II. Se um biólogo for contratado, então um novo congelador será adquirido. III. Se for adquirido um novo congelador ou uma nova geladeira, então o chefe comprará sorvete para todos. Até julho de 2013, nenhum biólogo havia sido contratado. Apenas com estas informações, pode-se concluir que, necessariamente, que","options":{"A":"o projeto X não foi aprovado até maio de 2013.","B":"nenhum químico foi contratado.","C":"não foi adquirido um novo congelador.","D":"não foi adquirida uma nova geladeira.","E":"o chefe não comprou sorvete para todos."},"answer":"A","visualRequired":false},{"id":"tec-173590","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - AJ TRT19/TRT 19/Apoio Especializado/Medicina Psiquiatria/2014","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":173590,"url":"https://www.tecconcursos.com.br/questoes/173590","page":23,"prompt":"Se o diretor está no escritório, então Rodrigo não joga no computador e Tomás não ouve rádio. Se Tomás não ouve rádio, então Gabriela pensa que Tomás não veio. Se Gabriela pensa que Tomás não veio, então ela fica mal humorada. Gabriela não está mal humorada. A partir dessas informações, é possível concluir, corretamente, que","options":{"A":"o diretor não está no escritório e Tomás não ouve rádio.","B":"Gabriela pensa que Tomás não veio e Tomás não ouve rádio.","C":"o diretor está no escritório e Tomás ouve rádio.","D":"Tomás não ouve rádio e Gabriela não pensa que Tomás não veio.","E":"o diretor não está no escritório e Gabriela não pensa que Tomás não veio."},"answer":"E","visualRequired":false},{"id":"tec-173666","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - TJ TRT19/TRT 19/Administrativa/\"Sem Especialidade\"/2014","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":173666,"url":"https://www.tecconcursos.com.br/questoes/173666","page":24,"prompt":"Considere verdadeiras as afirmações: I. Se Ana for nomeada para um novo cargo, então Marina permanecerá em seu posto. II. Marina não permanecerá em seu posto ou Juliana será promovida. III. Se Juliana for promovida então Beatriz fará o concurso. IV. Beatriz não fez o concurso. A partir dessas informações, pode-se concluir corretamente que","options":{"A":"Beatriz foi nomeada para um novo cargo.","B":"Marina permanecerá em seu posto.","C":"Beatriz não será promovida.","D":"Ana não foi nomeada para um novo cargo.","E":"Juliana foi promovida."},"answer":"D","visualRequired":false},{"id":"tec-200689","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - TJ TRT16/TRT 16/Administrativa/2014","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":200689,"url":"https://www.tecconcursos.com.br/questoes/200689","page":24,"prompt":"Ou como macarronada ou como arroz e feijão. Se estou com muita fome, então como arroz e feijão. Se não estou com muita fome, então como saladas. Hoje, na hora do almoço, não comi saladas. A partir dessas informações, pode-se concluir corretamente, que hoje, na hora do almoço,","options":{"A":"não estava com muita fome.","B":"não comi arroz e feijão.","C":"comi saladas no jantar.","D":"comi arroz e feijão.","E":"comi macarronada."},"answer":"D","visualRequired":false},{"id":"tec-211951","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - TJ TRF4/TRF 4/Administrativa/\"Sem Especialidade\"/2014","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":211951,"url":"https://www.tecconcursos.com.br/questoes/211951","page":24,"prompt":"Considere verdadeiras as afirmativas: Se não fui ao mercado, então não fiz compras. Comprei creme e sabonete. Ou comprei queijo ou comprei iogurte. Comprei cereal ou comprei pão. A partir dessas afirmações, pode-se concluir que","options":{"A":"não fui ao mercado.","B":"só comprei creme.","C":"fui ao mercado e comprei sabonete.","D":"não comprei nem queijo nem iogurte.","E":"não comprei cereal nem pão."},"answer":"C","visualRequired":false},{"id":"tec-212037","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - TJ TRF4/TRF 4/Apoio Especializado/Tecnologia da Informação/2014","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":212037,"url":"https://www.tecconcursos.com.br/questoes/212037","page":24,"prompt":"Considere verdadeiras as afirmações: Se vou ao cinema, então como pipoca. Se o lugar é marcado, então não posso sentar em outra cadeira. Fui ao cinema. A partir, apenas, dessas afirmações é possível concluir que","options":{"A":"o cinema não tinha pipoca.","B":"não posso sentar em outra cadeira.","C":"comi pipoca.","D":"não posso escolher o filme.","E":"o lugar no cinema é marcado."},"answer":"C","visualRequired":false},{"id":"tec-230640","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - TJ TRT1/TRT 1/Apoio Especializado/Tecnologia da Informação/2014","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":230640,"url":"https://www.tecconcursos.com.br/questoes/230640","page":25,"prompt":"Considere verdadeiras as afirmações: I. Se Manuel é engenheiro, então Edileuza não é médica. II. Ou João é analista, ou Ricardo é advogado. III. Se Ricardo não é advogado, então Edileuza é médica. IV. João é analista. A partir da veracidade das afirmações, conclui-se corretamente que","options":{"A":"Manuel é engenheiro ou Ricardo é advogado.","B":"Manuel não é engenheiro e Edileuza não é médica.","C":"Edileuza não é médica e João é analista.","D":"João é analista e Manuel é engenheiro.","E":"Manuel não é engenheiro e Ricardo não é advogado."},"answer":"E","visualRequired":false},{"id":"tec-230646","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - TJ TRT1/TRT 1/Apoio Especializado/Tecnologia da Informação/2014","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":230646,"url":"https://www.tecconcursos.com.br/questoes/230646","page":25,"prompt":"Considere as afirmações: I. Ou caí, ou escorreguei. II. Escorreguei ou tropecei. III. Caí ou deitei. IV. Tropecei ou deitei. V. Se escorreguei, então não deitei. Das afirmações, sabe-se que a afirmação (III) é falsa e as outras verdadeiras. Deste modo, conclui-se corretamente que","options":{"A":"Tropecei e escorreguei.","B":"Escorreguei e caí.","C":"Tropecei e deitei.","D":"Não escorreguei e tropecei.","E":"Caí e deitei."},"answer":"A","visualRequired":false},{"id":"tec-271728","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Ass Ad Jr (METRO SP)/METRO SP/Central Informação Manutenção/2014","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":271728,"url":"https://www.tecconcursos.com.br/questoes/271728","page":25,"prompt":"Ou Carlos fica nervoso ou Júlia grita. Se Manuel chega correndo, então Júlia não grita. Se Manuel não chega correndo, então Marina descansa. Marina não descansa. A partir dessas informações, pode-se concluir corretamente que","options":{"A":"Manuel chega correndo e Júlia grita.","B":"Marina descansa.","C":"Carlos não fica nervoso e Marina descansa.","D":"Carlos fica nervoso.","E":"Se Manuel não fica nervoso, então Marina grita."},"answer":"D","visualRequired":false},{"id":"tec-1021472","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Per (DPT BA)/DPT BA/Técnico de Polícia Civil/2014","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":1021472,"url":"https://www.tecconcursos.com.br/questoes/1021472","page":25,"prompt":"Considere as afirmações: I. Se Luiza não veste azul, então Marina veste amarelo. II. Ou Marina não veste amarelo, ou Carolina veste verde. III. Carolina veste verde ou Isabela veste preto. IV. Isabela não veste preto. Das afirmações acima, sabe-se que apenas a afirmação III é falsa. Desta maneira, pode-se concluir corretamente, que","options":{"A":"Luiza veste azul e Marina veste amarelo.","B":"Carolina veste verde e Isabela veste preto.","C":"Luiza não veste azul ou Marina veste amarelo.","D":"Carolina não veste verde e Luiza veste azul.","E":"Marina veste amarelo ou Isabela veste preto."},"answer":"D","visualRequired":false},{"id":"tec-2638135","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - TJ (TJ AP)/TJ AP/Judiciária e Administrativa/2014","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":2638135,"url":"https://www.tecconcursos.com.br/questoes/2638135","page":26,"prompt":"As frases I e II são verdadeiras. A frase III é falsa. I. Jogo tênis ou pratico caminhada. II. Se pratico caminhada, então não sou preguiçoso. III. Não sou preguiçoso ou estou cansado. A partir dessas informações, é possível concluir corretamente que","options":{"A":"jogo tênis e estou cansado.","B":"pratico caminhada e sou preguiçoso.","C":"ou estou cansado ou não pratico caminhada.","D":"estou cansado ou jogo tênis.","E":"pratico caminhada ou estou cansado."},"answer":"D","visualRequired":false},{"id":"tec-2638136","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - TJ (TJ AP)/TJ AP/Judiciária e Administrativa/2014","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":2638136,"url":"https://www.tecconcursos.com.br/questoes/2638136","page":26,"prompt":"Três amigos exercem profissões diferentes e praticam esportes diferentes. As profissões exercidas por eles são: advocacia, engenharia e medicina. Os esportes praticados são: futebol, basquetebol e voleibol. Sabe-se que Alberto não é médico e Carlos não é médico. Ou o Bruno pratica voleibol ou o Bruno pratica basquetebol. Se o Bruno não pratica futebol, então Alberto não é advogado. Carlos pratica voleibol. Com essas informações é possível determinar corretamente que","options":{"A":"Bruno pratica voleibol e exerce a engenharia.","B":"Carlos exerce a advocacia e pratica voleibol.","C":"Alberto exerce a advocacia e pratica basquetebol.","D":"Bruno exerce a medicina e pratica futebol.","E":"Alberto exerce a engenharia e pratica basquetebol."},"answer":"B","visualRequired":false},{"id":"tec-178974","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Ana Proc (PGE BA)/PGE BA/Administrativo/2013","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":178974,"url":"https://www.tecconcursos.com.br/questoes/178974","page":26,"prompt":"Se Marcus é violonista, então Flávia é flautista. Se Flávia é flautista, então Carlos toca ao piano uma valsa. Se Carlos toca ao piano uma valsa, então Arlete é sanfoneira. Sabendo-se que Arlete não é sanfoneira, é correto concluir que","options":{"A":"Carlos não toca ao piano uma valsa e Marcus não é violonista.","B":"Flávia não é flautista e Carlos toca ao piano uma valsa.","C":"Marcus não é violonista e Carlos toca ao piano uma valsa.","D":"Flávia é flautista e Carlos toca ao piano uma valsa.","E":"Marcus é violonista e Flávia é flautista."},"answer":"A","visualRequired":false},{"id":"tec-178975","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Ana Proc (PGE BA)/PGE BA/Administrativo/2013","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":178975,"url":"https://www.tecconcursos.com.br/questoes/178975","page":26,"prompt":"Se João amava Teresa, então Lili é vizinha de Teresa. Lili não é vizinha de Teresa. Se João não é vizinho de Teresa, então João amava Teresa. Logo","options":{"A":"João é vizinho de Lili e amava Teresa.","B":"João amava Lili e amava Teresa.","C":"João amava Teresa ou não é vizinho de Teresa.","D":"João não amava Teresa ou não é vizinho de Lili.","E":"João amava Teresa e não é vizinho de Lili."},"answer":"D","visualRequired":false},{"id":"tec-178979","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Ana Proc (PGE BA)/PGE BA/Administrativo/2013","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":178979,"url":"https://www.tecconcursos.com.br/questoes/178979","page":26,"prompt":"Alice irá ao País das Maravilhas quando imaginar ou perder o medo. Se Alice perder o medo,","options":{"A":"Alice não irá ao País das Maravilhas, pois não vai imaginar.","B":"Alice irá ao País das Maravilhas.","C":"Alice vai necessariamente imaginar.","D":"Alice não irá, também, imaginar.","E":"Alice não vai imaginar."},"answer":"B","visualRequired":false},{"id":"tec-179339","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Ass Proc (PGE BA)/PGE BA/2013","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":179339,"url":"https://www.tecconcursos.com.br/questoes/179339","page":26,"prompt":"Se todas as bananas têm asas, então o ouro não é um fruto seco. Se o ouro não é um fruto seco, então todas as bananas têm asas. Logo,","options":{"A":"todas as bananas não têm asas se e somente se o ouro não for um fruto seco.","B":"todas as bananas têm asas se e somente se o ouro for um fruto seco.","C":"todas as bananas não têm asas se o ouro é um fruto seco.","D":"todas as bananas têm asas se e somente se o ouro não for um fruto seco.","E":"algum ouro não é um fruto seco se e somente se todas as bananas tiverem asas."},"answer":"D","visualRequired":false},{"id":"tec-179340","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Ass Proc (PGE BA)/PGE BA/2013","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":179340,"url":"https://www.tecconcursos.com.br/questoes/179340","page":27,"prompt":"Sou pai de Pedro ou sou pai de Francisco. Sou pai de Ana ou não sou pai de Pedro. Sou pai de Beatriz ou não sou pai de Francisco. Ora, não sou pai de Beatriz. Deste modo,","options":{"A":"não sou pai de Ana e sou pai de Pedro.","B":"não sou pai de Beatriz e não sou pai de Ana.","C":"sou pai de Francisco e pai de Ana.","D":"sou pai de Ana e pai de Pedro.","E":"sou pai de Francisco e não sou pai de Beatriz."},"answer":"D","visualRequired":false},{"id":"tec-77713","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Aux Tec Fis (TCE-SP)/TCE SP/Tecnologia da Informação (TI)/2012","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":77713,"url":"https://www.tecconcursos.com.br/questoes/77713","page":27,"prompt":"Para escolher a roupa que irá vestir em uma entrevista de emprego, Estela precisa decidir entre uma camisa branca e uma vermelha, entre uma calça azul e uma preta e entre um par de sapatos preto e outro azul. Quatro amigas de Estela deram as seguintes sugestões: Amiga 1 → Se usar a calça azul, então vá com os sapatos azuis. Amiga 2 → Se vestir a calça preta, então não use a camisa branca. Amiga 3 → Se optar pela camisa branca, então calce os sapatos pretos. Amiga 4 → Se escolher a camisa vermelha, então vá com a calça azul. Sabendo que Estela acatou as sugestões das quatro amigas, conclui-se que ela vestiu","options":{"A":"a camisa branca com a calça e os sapatos azuis.","B":"a camisa branca com a calça e os sapatos pretos.","C":"a camisa vermelha com a calça e os sapatos azuis.","D":"a camisa vermelha com a calça e os sapatos pretos.","E":"a camisa vermelha com a calça azul e os sapatos pretos."},"answer":"C","visualRequired":false},{"id":"tec-77793","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - ACE (TCE SP)/TCE SP/Administração/2012","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":77793,"url":"https://www.tecconcursos.com.br/questoes/77793","page":27,"prompt":"Se a tinta é de boa qualidade então a pintura melhora a aparência do ambiente. Se o pintor é um bom pintor até usando tinta ruim a aparência do ambiente melhora. O ambiente foi pintado. A aparência do ambiente melhorou. Então, a partir dessas afirmações, é verdade que:","options":{"A":"O pintor era um bom pintor ou a tinta era de boa qualidade.","B":"O pintor era um bom pintor e a tinta era ruim.","C":"A tinta não era de boa qualidade.","D":"A tinta era de boa qualidade e o pintor não era bom pintor.","E":"Bons pintores não usam tinta ruim."},"answer":"A","visualRequired":false},{"id":"tec-186429","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - TJ TRT11/TRT 11/Apoio Especializado/Enfermagem/2012","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":186429,"url":"https://www.tecconcursos.com.br/questoes/186429","page":27,"prompt":"Um analista esportivo afirmou: “Sempre que o time X joga em seu estádio marca pelo menos dois gols.” De acordo com essa afirmação, conclui-se que, necessariamente,","options":{"A":"o time X marca mais gols em seu estádio do que fora dele.","B":"o time X marca menos de dois gols quando joga fora de seu estádio.","C":"se o time X marcar um único gol em um jogo, este terá ocorrido fora de seu estádio.","D":"se o time X marcar três gols em um jogo, este terá ocorrido em seu estádio.","E":"o time X nunca é derrotado quando joga em seu estádio."},"answer":"C","visualRequired":false},{"id":"tec-432402","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Sold (PM BA)/PM BA/2012","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":432402,"url":"https://www.tecconcursos.com.br/questoes/432402","page":27,"prompt":"Se João for trabalhar, então Maria fará o jantar. Se Maria não fizer o jantar, então Lucas passará fome. Maria não fez o jantar. Pode-se certamente concluir que","options":{"A":"Lucas fez o jantar.","B":"João foi trabalhar.","C":"Lucas não passou fome.","D":"João fez o jantar.","E":"Lucas passou fome."},"answer":"E","visualRequired":false},{"id":"tec-432404","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Sold (PM BA)/PM BA/2012","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":432404,"url":"https://www.tecconcursos.com.br/questoes/432404","page":28,"prompt":"Se chover, então o jogo será adiado. Se chover e ventar, então o jogo será cancelado. Sabe-se que choveu. Pode-se certamente concluir que","options":{"A":"o jogo empatou,","B":"o jogo foi adiado.","C":"só aconteceu o primeiro tempo do jogo.","D":"o jogo aconteceu.","E":"o jogo foi cancelado."},"answer":"B","visualRequired":false},{"id":"tec-548425","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - AJ (TJ RJ)/TJ RJ/Tecnologia da Informação/Analista de Sistemas/2012","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":548425,"url":"https://www.tecconcursos.com.br/questoes/548425","page":28,"prompt":"Considere a seguinte análise, feita por um comentarista esportivo durante um torneio de futebol. Se o Brasil vencer ou empatar o jogo contra o Equador, então estará classificado para a semifinal, independentemente de outros resultados. Classificando-se para a semifinal, a equipe brasileira vai enfrentar o Uruguai. De acordo com essa análise, conclui-se que se o Brasil","options":{"A":"não enfrentar o Uruguai, necessariamente terá perdido o jogo para o Equador.","B":"não se classificar para a semifinal, terá necessariamente empatado o jogo com o Equador.","C":"enfrentar o Uruguai, necessariamente terá vencido ou empatado seu jogo contra o Equador.","D":"perder seu jogo contra o Equador, necessariamente não se classificará para a semifinal.","E":"se classificar para a semifinal, então necessariamente não terá sido derrotado pelo Equador."},"answer":"A","visualRequired":false},{"id":"tec-62516","module":"M04","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - ACE (TCE PR)/TCE PR/Engenharia/2011","topic":"Raciocínio Lógico - Argumentos - Métodos Decorrentes da Tabela Verdade","tecId":62516,"url":"https://www.tecconcursos.com.br/questoes/62516","page":28,"prompt":"Considere que as seguintes premissas são verdadeiras: I. Se um homem é prudente, então ele é competente. II. Se um homem não é prudente, então ele é ignorante. III. Se um homem é ignorante, então ele não tem esperanças. IV. Se um homem é competente, então ele não é violento. Para que se obtenha um argumento válido, é correto concluir que se um homem","options":{"A":"não é violento, então ele é prudente.","B":"não é competente, então ele é violento.","C":"é violento, então ele não tem esperanças.","D":"não é prudente, então ele é violento.","E":"não é violento, então ele não é competente."},"answer":"C","visualRequired":false},{"id":"tec-3362673","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - AMCI (CGM SP)/Pref SP/Correição/2025","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":3362673,"url":"https://www.tecconcursos.com.br/questoes/3362673","page":28,"prompt":"A negação da afirmação \"se toda arara agarra e amarra, então toda arara rara é de Araraquara.\" é logicamente equivalente a","options":{"A":"se alguma arara agarra e amarra, então alguma arara rara é de Araraquara.","B":"se nenhuma arara rara é de Araraquara, então alguma arara agarra e amarra.","C":"toda arara agarra e amarra e nenhuma arara rara é de Araraquara.","D":"toda arara agarra e amarra, mas existe arara rara que não é de Araraquara.","E":"nem toda arara agarra e amarra, mas alguma arara rara é de Araraquara."},"answer":"D","visualRequired":false},{"id":"tec-3558003","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - ATE (SEFAZ PI)/SEFAZ PI/Tecnologia da Informação/2025","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":3558003,"url":"https://www.tecconcursos.com.br/questoes/3558003","page":28,"prompt":"Se \"Alguns poetas são músicos\" e \"Nenhum músico é atleta\", conclui-se corretamente que","options":{"A":"todo poeta é músico.","B":"todo músico é poeta.","C":"nenhum poeta é atleta.","D":"algum poeta não é atleta.","E":"algum atleta é músico."},"answer":"D","visualRequired":false},{"id":"tec-3121633","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - GM (J Guararapes)/Pref J Guararapes/2024","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":3121633,"url":"https://www.tecconcursos.com.br/questoes/3121633","page":29,"prompt":"Considere que seja verdade que todo adolescente joga vídeo-game, que existem adultos que jogam videogame e que pelo menos um adolescente é programador. A partir apenas dessas afirmações, é necessariamente verdade que","options":{"A":"pelo menos um adolescente não é programador.","B":"existe programador que não é adolescente e que joga videogame.","C":"todo adolescente que é programador Joga vídeo-game.","D":"apenas um programador é adolescente.","E":"quem joga vídeo-game é adolescente."},"answer":"C","visualRequired":false},{"id":"tec-2113971","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - AJ TRT4/TRT 4/Judiciária/\"Sem Especialidade\"/2022","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":2113971,"url":"https://www.tecconcursos.com.br/questoes/2113971","page":29,"prompt":"Em determinada escola de línguas, todos os professores que ensinam chinês ensinam, também, inglês. Nessa escola há, pelo menos, um professor que ensina alemão e chinês, e há, pelo menos, um professor que ensina francês e inglês. É correto afirmar que, nessa escola de línguas, necessariamente,","options":{"A":"todos os professores que ensinam alemão ensinam, também, inglês.","B":"há, pelo menos, um professor que ensina alemão e francês.","C":"há, pelo menos, um professor que ensina francês e chinês.","D":"há, pelo menos, um professor que ensina inglês e alemão.","E":"todos os professores que ensinam inglês ensinam, também, francês."},"answer":"D","visualRequired":false},{"id":"tec-2132517","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - AJ TRT19/TRT 19/Apoio Especializado/Tecnologia da Informação/2022","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":2132517,"url":"https://www.tecconcursos.com.br/questoes/2132517","page":29,"prompt":"Todas as bailarinas são magras. Logo, necessariamente,","options":{"A":"o conjunto das bailarinas contém o conjunto das pessoas magras.","B":"o conjunto das pessoas magras contém o conjunto das bailarinas.","C":"todas as mulheres magras são bailarinas.","D":"alguma bailarina não é magra.","E":"toda mulher magra não é bailarina."},"answer":"B","visualRequired":false},{"id":"tec-2193734","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Sold (PM)/PM AP/Combatente/2022","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":2193734,"url":"https://www.tecconcursos.com.br/questoes/2193734","page":29,"prompt":"Nenhum Médico desgosta de Biologia. Certos Médicos também são Químicos. Em consequência dessas proposições, é correto afirmar que","options":{"A":"alguns Químicos desgostam de Biologia.","B":"alguns Químicos gostam de Biologia.","C":"quem gosta de Biologia é Médico.","D":"quem é Químico gosta de Biologia.","E":"Médicos podem ser Químicos que não gostam de Biologia."},"answer":"B","visualRequired":false},{"id":"tec-1821195","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - ARE IV (SEF SC)/SEF SC/2021","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":1821195,"url":"https://www.tecconcursos.com.br/questoes/1821195","page":29,"prompt":"Em um processo de licitação para o fornecimento de um sistema de informática a uma secretaria estadual, todas as empresas inscritas tiveram de submeter seus sistemas a diversos testes de desempenho. Em um desses testes, a condição para aprovação de um sistema era a seguinte: Todos os usuários da secretaria devem conseguir acessar o sistema e nenhum deles deve receber uma mensagem de erro ao enviar um e-mail. Sabe-se que o sistema da empresa X não foi aprovado nesse teste. Assim, é correto concluir que durante o teste do sistema dessa empresa, necessariamente,","options":{"A":"nenhum usuário da secretaria conseguiu acessar o sistema ou todos os usuários da secretaria receberam uma mensagem de erro ao enviar um e-mail.","B":"todos os usuários da secretaria que conseguiram acessar o sistema receberam uma mensagem de erro ao enviar um e-mail.","C":"pelo menos um usuário da secretaria não conseguiu acessar o sistema ou algum deles recebeu uma mensagem de erro ao enviar um e-mail.","D":"algum usuário da secretaria não conseguiu acessar o sistema e pelo menos um dos que conseguiram acessar recebeu uma mensagem de erro ao enviar um e- mail.","E":"um grupo de usuários da secretaria não conseguiu acessar o sistema e, dentre os que conseguiram, ao menos um recebeu uma mensagem de erro ao enviar um e-mail."},"answer":"C","visualRequired":false},{"id":"tec-1896526","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - AP (MANAUSPREV)/MANAUSPREV/Administração/2021","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":1896526,"url":"https://www.tecconcursos.com.br/questoes/1896526","page":29,"prompt":"Considerando que a proposição “Todos os advogados já leram a Constituição” seja verdadeira, Rui conclui que: I. se André leu a Constituição, então ele é advogado; II. se Bernardo não leu a constituição, então ele não é advogado; III. se Cléber não é advogado, então ele não leu a constituição. Das conclusões de Rui, APENAS","options":{"A":"I está correta.","B":"II está correta.","C":"III está correta.","D":"I e III estão corretas.","E":"II e III estão corretas."},"answer":"B","visualRequired":false},{"id":"tec-1240663","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Ass Leg (ALAP)/ALAP/Atividade Administrativa e Operacional/Assistente Administrativo/2020","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":1240663,"url":"https://www.tecconcursos.com.br/questoes/1240663","page":30,"prompt":"A negativa da afirmação \" Todos os homens carregam todas suas malas\" é","options":{"A":"Nenhum homem carrega todas suas malas.","B":"Todos os homens carregam apenas uma de suas malas.","C":"Pelo menos um homem não carrega nenhuma de suas malas.","D":"Todos os homens não carregam nenhuma de suas malas.","E":"Pelo menos um homem não carrega todas suas malas."},"answer":"E","visualRequired":false},{"id":"tec-758237","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - AG (Pref Recife)/Pref Recife/Administrativa/2019","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":758237,"url":"https://www.tecconcursos.com.br/questoes/758237","page":30,"prompt":"Considere que “ um profissional é formado pela Faculdade X” seja uma condição suficiente para “ele presta serviço para a empresa E”. É correto afirmar que","options":{"A":"a maioria dos profissionais que trabalham para a empresa E são formados pela Faculdade X.","B":"somente os profissionais que são formados pela Faculdade X prestam serviços para a empresa E.","C":"um profissional que não é formado pela Faculdade X não presta serviço para a empresa E.","D":"qualquer profissional que presta serviço para a empresa E é formado pela Faculdade X.","E":"não existe um profissional formado pela Faculdade X e que não presta serviços para a Empresa E."},"answer":"E","visualRequired":false},{"id":"tec-758352","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - AG (Pref Recife)/Pref Recife/Contábil/2019","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":758352,"url":"https://www.tecconcursos.com.br/questoes/758352","page":30,"prompt":"Considere a seguinte proposição: “Todos os profissionais formados pela Faculdade Alfa estão empregados.”. Admitindo que ela seja falsa, então certamente","options":{"A":"Todos profissionais formados pela Faculdade Alfa estão desempregados.","B":"Existe pelo menos um profissional formado pela Faculdade Alfa que não está empregado.","C":"Se o profissional Roberto está desempregado, então ele é formado pela Faculdade Alfa.","D":"Nenhum profissional formado pela Faculdade Alfa está empregado.","E":"Alguns profissionais formados pela Faculdade Alfa estão empregados."},"answer":"B","visualRequired":false},{"id":"tec-758685","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - AG (Pref Recife)/Pref Recife/Planejamento e Orçamento/2019","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":758685,"url":"https://www.tecconcursos.com.br/questoes/758685","page":30,"prompt":"Seja a seguinte proposição: “ Se um profissional é formado em Administração, então ele está apto a realizar determinado trabalho.” Pode-se afirmar que","options":{"A":"somente quem é formado em Administração está apto a realizar determinado trabalho.","B":"a maioria dos profissionais que estão aptos a realizar determinado trabalho são formados em Administração.","C":"se Roberto está apto a realizar determinado trabalho, conclui-se que ele é formado em Administração.","D":"é possível que exista um profissional que está apto a realizar determinado trabalho e não seja formado em Administração.","E":"se Miguel não é formado em Administração, conclui-se que ele não está apto a realizar determinado trabalho."},"answer":"D","visualRequired":false},{"id":"tec-758795","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - AssGP (Pref Recife)/Pref Recife/2019","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":758795,"url":"https://www.tecconcursos.com.br/questoes/758795","page":30,"prompt":"Em uma escola de línguas, todos os professores que falam alemão falam, também, inglês, e nenhum dos professores que fala inglês fala italiano. Sobre os professores dessa escola de línguas, é correto afirmar que todos os que","options":{"A":"falam alemão falam, também, italiano.","B":"falam italiano não falam alemão.","C":"falam italiano falam, também, alemão.","D":"não falam italiano falam alemão.","E":"não falam alemão falam italiano."},"answer":"B","visualRequired":false},{"id":"tec-790858","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Ass Adm Fom (AFAP)/AFAP/2019","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":790858,"url":"https://www.tecconcursos.com.br/questoes/790858","page":30,"prompt":"Considere as seguintes afirmações: I. Todo amapaense é brasileiro. II. Todo brasileiro é sul-americano. Então, é correto afirmar:","options":{"A":"Todo brasileiro é amapaense.","B":"Todo sul-americano é brasileiro.","C":"Existe amapaense que não é brasileiro.","D":"Existe brasileiro que não é sul-americano.","E":"É possível que exista um sul-americano que não seja amapaense."},"answer":"E","visualRequired":false},{"id":"tec-794167","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Esc (BANRISUL)/BANRISUL/2019","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":794167,"url":"https://www.tecconcursos.com.br/questoes/794167","page":31,"prompt":"Dentre os funcionários de uma determinada agência bancária, os gerentes são todos casados e têm filhos. Nenhum funcionário casado mora na capital, mas há funcionários que moram na capital e têm filhos. Nessas condições,","options":{"A":"nenhum funcionário que tem filhos é casado.","B":"todos os funcionários que têm filhos são casados.","C":"há gerentes que moram na capital.","D":"todos os funcionários que têm filhos moram na capital.","E":"nenhum funcionário que mora na capital é gerente."},"answer":"E","visualRequired":false},{"id":"tec-866917","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - AFTM (Pref Manaus)/Pref Manaus/2019","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":866917,"url":"https://www.tecconcursos.com.br/questoes/866917","page":31,"prompt":"Para José, uma caixa de ferramentas é boa se, e somente se, para todo parafuso que houver na caixa, houver, também, uma chave que encaixa nele. Assim, se uma caixa de ferramentas não é boa para José, então, nela:","options":{"A":"existe pelo menos uma chave que não encaixa em nenhum parafuso.","B":"nenhum parafuso encaixa em todas as chaves.","C":"existe pelo menos um parafuso que não encaixa em nenhuma chave.","D":"para cada parafuso, existe pelo menos uma chave que não encaixa nele.","E":"existe pelo menos um parafuso que encaixa em todas as chaves."},"answer":"C","visualRequired":false},{"id":"tec-866976","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Ass TF (Pref Manaus)/Pref Manaus/\"Sem Área\"/2019","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":866976,"url":"https://www.tecconcursos.com.br/questoes/866976","page":31,"prompt":"Em um curso preparatório para vestibulares, todos os professores que ensinam física ou química ensinam também matemática, e nenhum dos professores que ensinam biologia ensina também matemática. Logo,","options":{"A":"nenhum dos professores que ensinam física ensina também biologia.","B":"todos os professores que ensinam tanto física quanto química ensinam também biologia.","C":"há professores que ensinam química e biologia.","D":"todos os professores que ensinam matemática e não ensinam química ensinam biologia.","E":"há professores que ensinam física e biologia."},"answer":"A","visualRequired":false},{"id":"tec-881576","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Tec Faz (Pref Manaus)/Pref Manaus/2019","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":881576,"url":"https://www.tecconcursos.com.br/questoes/881576","page":31,"prompt":"Uma conferência foi composta de 5 sessões. Todos os participantes da sessão A participaram, também, da sessão B. Nenhum participante da sessão B participou das sessões C ou E. Todos os participantes da sessão D participaram, também da sessão E, e alguns dos participantes da sessão E participaram da sessão C. Nenhum participante da sessão D participou da sessão C. É correto concluir que","options":{"A":"todos os participantes da sessão E participaram, também, da sessão D.","B":"nenhum participante da sessão D participou, também, da sessão A.","C":"pelo menos um participante da sessão E participou, também, da sessão A.","D":"pelo menos um participante da sessão D participou, também, da sessão B.","E":"nenhum participante da sessão B participou, também, da sessão A."},"answer":"B","visualRequired":false},{"id":"tec-881750","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - TTIFM (Pref Manaus)/Pref Manaus/2019","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":881750,"url":"https://www.tecconcursos.com.br/questoes/881750","page":31,"prompt":"Em uma escola bilíngue, há vários estudantes brasileiros, e todos eles vão bem em português e matemática. Além disso, todo estudante que vai bem em matemática vai bem, também, em física. Nessa escola, há estudantes que vão bem em física, mas não em matemática, e há estudantes que vão bem em português, mas não em física. Logo, nessa escola,","options":{"A":"todo estudante que vai bem em português vai bem, também, em matemática.","B":"há estudantes que vão bem em português e em física.","C":"todo estudante que vai bem em física é brasileiro.","D":"há estudantes brasileiros que não vão bem em física.","E":"todo estudante que vai bem em português é brasileiro."},"answer":"B","visualRequired":false},{"id":"tec-881753","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - TTIFM (Pref Manaus)/Pref Manaus/2019","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":881753,"url":"https://www.tecconcursos.com.br/questoes/881753","page":32,"prompt":"Em uma galáxia fictícia, existem três grupos de seres: os alidianos, os surapianos e os travigianos. Considere as afirmações abaixo sobre esses seres. I. Todo alidiano é, também, surapiano. II. Existe pelo menos um alidiano que não é surapiano. III. Todo surapiano é, também, travigiano. Sabendo que apenas uma das três afirmações é falsa, é correto concluir que, necessariamente,","options":{"A":"todos os alidianos são travigianos.","B":"nenhum surapiano é alidiano.","C":"todos os travigianos são surapianos.","D":"existe pelo menos um alidiano que é surapiano.","E":"existe pelo menos um surapiano que é travigiano."},"answer":"E","visualRequired":false},{"id":"tec-882122","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - ATTIFM (Pref Manaus)/Pref Manaus/Programador/2019","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":882122,"url":"https://www.tecconcursos.com.br/questoes/882122","page":32,"prompt":"Todos os sócios de um clube esportivo que jogam handebol jogam também futebol, mas há sócios que jogam futebol e não jogam handebol. Alguns sócios que jogam voleibol jogam também basquete, mas nenhum sócio que joga basquete ou voleibol joga futebol. Logo, todos os sócios que","options":{"A":"não jogam handebol jogam basquete.","B":"jogam handebol jogam voleibol.","C":"jogam voleibol jogam handebol.","D":"jogam handebol não jogam basquete.","E":"não jogam basquete jogam handebol."},"answer":"D","visualRequired":false},{"id":"tec-882124","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - ATTIFM (Pref Manaus)/Pref Manaus/Programador/2019","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":882124,"url":"https://www.tecconcursos.com.br/questoes/882124","page":32,"prompt":"Se não é verdade que, no ano passado, em todos os sábados, se fazia sol, Rodrigo passeava de bicicleta, então, no ano passado,","options":{"A":"em nenhum sábado que não fez sol, Rodrigo passeou de bicicleta.","B":"em todos os sábados que não fez sol, Rodrigo não passeou de bicicleta.","C":"houve um sábado em que não fez sol e Rodrigo passeou de bicicleta.","D":"em todos os sábados fez sol e Rodrigo passeou de bicicleta.","E":"houve um sábado em que fez sol e Rodrigo não passeou de bicicleta."},"answer":"E","visualRequired":false},{"id":"tec-943374","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - AJ TRF4/TRF 4/Judiciária/\"Sem Especialidade\"/2019","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":943374,"url":"https://www.tecconcursos.com.br/questoes/943374","page":32,"prompt":"Sabendo-se que é verdadeira a afirmação “Todos os filhos de José sabem inglês”, então é verdade que","options":{"A":"José sabe inglês.","B":"José não sabe inglês.","C":"se Mário sabe inglês então ele é filho de José.","D":"se Murilo não sabe inglês então ele não é filho de José.","E":"se Marcos não é filho de José então ele não sabe inglês."},"answer":"D","visualRequired":false},{"id":"tec-957001","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Estag (SABESP)/SABESP/Ensino Médio Regular/2019","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":957001,"url":"https://www.tecconcursos.com.br/questoes/957001","page":32,"prompt":"Se é verdade que alguns homens altos são bonitos e todos os homens altos são inteligentes, pode-se concluir, a partir dessa proposição, que","options":{"A":"todo homem bonito é inteligente.","B":"todo homem inteligente é alto.","C":"todo homem não inteligente é bonito.","D":"algum homem inteligente não é alto.","E":"algum homem bonito é inteligente."},"answer":"E","visualRequired":false},{"id":"tec-957276","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Estag (SABESP)/SABESP/Ensino Médio Técnico/2019","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":957276,"url":"https://www.tecconcursos.com.br/questoes/957276","page":32,"prompt":"Considere que as seguintes premissas são verdadeiras: − Todo bombeiro sabe nadar. − Geraldo é contador. − Alguns contadores sabem nadar. De acordo com essas premissas, é correto afirmar:","options":{"A":"Geraldo é bombeiro.","B":"Existem bombeiros que são contadores.","C":"Todo contador que também é bombeiro sabe nadar.","D":"Geraldo não sabe nadar.","E":"Alguns contadores que sabem nadar, também são bombeiros."},"answer":"C","visualRequired":false},{"id":"tec-1009983","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Ag SegM (METRO SP)/METRO SP/2019","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":1009983,"url":"https://www.tecconcursos.com.br/questoes/1009983","page":33,"prompt":"Dada a proposição: “Nunca me canso e pratico esportes diariamente”, sua NEGAÇÃO LÓGICA é:","options":{"A":"Às vezes pratico esportes diariamente e às vezes me canso.","B":"Às vezes me canso ou não pratico esportes diariamente.","C":"Se pratico esportes diariamente, então me canso.","D":"Se pratico esportes diariamente, então não me canso.","E":"Ou me canso ou não pratico esportes diariamente."},"answer":"B","visualRequired":false},{"id":"tec-614359","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - AnaT (DETRAN MA)/DETRAN MA/2018","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":614359,"url":"https://www.tecconcursos.com.br/questoes/614359","page":33,"prompt":"De acordo com o Código de Trânsito Brasileiro, todo motorista flagrado dirigindo sob influência de álcool receberá uma multa e terá sua habilitação suspensa por um ano. A partir dessa informação, é correto concluir que, necessariamente,","options":{"A":"todo motorista que tiver recebido uma multa foi flagrado dirigindo sob influência de álcool.","B":"todo motorista com a habilitação suspensa por um ano foi flagrado dirigindo sob influência de álcool.","C":"somente se um motorista tiver sua habilitação suspensa por um ano ele poderá receber uma multa.","D":"se um motorista não foi flagrado dirigindo sob influência de álcool então ele não pode ter sua habilitação suspensa por um ano.","E":"se um motorista não teve sua habilitação suspensa por um ano então ele não foi f lagrado dirigindo sob influência de álcool."},"answer":"E","visualRequired":false},{"id":"tec-623470","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Of Log Al (METRO SP)/METRO SP/I (ingresso)/2018","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":623470,"url":"https://www.tecconcursos.com.br/questoes/623470","page":33,"prompt":"Considere verdadeiras as afirmações: − Alguns trabalhadores são estudantes. − Todos os estudantes são esperançosos. A partir dessas afirmações, é correto concluir que","options":{"A":"nenhum estudante é trabalhador.","B":"todo estudante que não é trabalhador é esperançoso.","C":"todos os trabalhadores são esperançosos.","D":"os esperançosos que não são estudantes não são trabalhadores.","E":"qualquer esperançoso é estudante."},"answer":"B","visualRequired":false},{"id":"tec-638445","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Estag (SABESP)/SABESP/Ensino Médio Regular/2018","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":638445,"url":"https://www.tecconcursos.com.br/questoes/638445","page":33,"prompt":"A negação lógica da afirmação: \"Todos alunos vieram para a aula\", está contida na alternativa:","options":{"A":"A sala está cheia de alunos.","B":"Pelo menos um aluno não veio para a aula.","C":"Quase todos os alunos faltaram.","D":"Todos os alunos faltaram à aula.","E":"Várias pessoas estão na sala, mas nem todos são alunos."},"answer":"B","visualRequired":false},{"id":"tec-638531","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Estag (SABESP)/SABESP/Ensino Médio Técnico/2018","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":638531,"url":"https://www.tecconcursos.com.br/questoes/638531","page":33,"prompt":"Nenhum brasileiro é fijiano (nascido nas Ilhas Fiji). Todos os fijianos nasceram em uma ilha. Do ponto de vista da lógica, decorre apenas dessas afirmações que","options":{"A":"alguém nascido em uma ilha não é fijiano.","B":"algum fijiano não nasceu em uma ilha.","C":"algum brasileiro é nascido em uma ilha.","D":"nenhum brasileiro nasceu em uma ilha.","E":"alguém nascido em uma ilha não é brasileiro."},"answer":"E","visualRequired":false},{"id":"tec-638633","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Estag (SABESP)/SABESP/Ensino Superior/2018","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":638633,"url":"https://www.tecconcursos.com.br/questoes/638633","page":33,"prompt":"Se todo engenheiro é bom em matemática e alguns artistas não são bons em matemática, então,","options":{"A":"todo engenheiro é artista.","B":"alguns artistas são engenheiros.","C":"alguns artistas não são engenheiros.","D":"nenhum artista é engenheiro.","E":"todo artista é engenheiro."},"answer":"C","visualRequired":false},{"id":"tec-641049","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Tec Leg (ALESE)/ALESE/Apoio Técnico Administrativo/2018","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":641049,"url":"https://www.tecconcursos.com.br/questoes/641049","page":34,"prompt":"O diagrama representa algumas informações sobre a escolaridade dos moradores de um município. Dados: I: conjunto de todos os moradores que concluíram um curso de inglês. E: conjunto de todos os moradores que concluíram um curso de espanhol. S: conjunto de todos os moradores que concluíram o Ensino Superior. Em todas as seis regiões do diagrama, há pelo menos um morador representado. Assim, é correto afirmar que se um morador dessa cidade","options":{"A":"concluiu um curso de inglês, então ele necessariamente concluiu um curso de espanhol.","B":"concluiu um curso de inglês e um de espanhol, então ele necessariamente concluiu o Ensino Superior.","C":"não concluiu um curso de espanhol, então ele necessariamente não concluiu o Ensino Superior.","D":"não concluiu um curso de inglês, então ele necessariamente não concluiu um curso de espanhol.","E":"não concluiu um curso de inglês, então ele necessariamente não concluiu o Ensino Superior."},"answer":"E","visualRequired":true},{"id":"tec-641058","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Tec Leg (ALESE)/ALESE/Apoio Técnico Administrativo/2018","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":641058,"url":"https://www.tecconcursos.com.br/questoes/641058","page":34,"prompt":"Em uma empresa, todos os funcionários devem receber vale-refeição mensalmente e nenhum deles pode fazer mais do que 20 horas extras em um mesmo mês. O setor de recursos humanos da empresa identificou que essa regra não foi cumprida em determinado mês. Dessa forma, é correto concluir que nesse mês, necessariamente,","options":{"A":"nenhum funcionário recebeu vale-refeição e alguns deles fizeram mais do que 20 horas extras.","B":"alguns funcionários não receberam vale-refeição e pelo menos um deles fez mais do que 20 horas extras.","C":"aqueles funcionários que fizeram menos do que 20 horas extras não receberam vale-refeição.","D":"todos os funcionários deixaram de receber vale-refeição ou fizeram mais do que 20 horas extras.","E":"pelo menos um funcionário não recebeu vale-refeição ou fez mais do que 20 horas extras."},"answer":"E","visualRequired":false},{"id":"tec-686715","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - AJ TRT2/TRT 2/Apoio Especializado/Serviço Social/2018","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":686715,"url":"https://www.tecconcursos.com.br/questoes/686715","page":34,"prompt":"Considere os conjuntos, suas respectivas intersecções e a existência de elementos em todas as regiões do diagrama. A partir dessas informações é correto concluir que","options":{"A":"qualquer elemento de J que não seja elemento de Q é elemento de M.","B":"há elemento de K que, além de ser de K, é também elemento de J, mas apenas de J.","C":"os elementos de M, que também são elementos de Q, não são apenas elementos desses dois conjuntos.","D":"todo e qualquer elemento de Q é elemento de pelo menos mais dois conjuntos.","E":"há elemento de M que seja elemento apenas de M e Q."},"answer":"C","visualRequired":true},{"id":"tec-687475","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Ana Leg (CL DF)/CL DF/Técnico Legislativo/2018","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":687475,"url":"https://www.tecconcursos.com.br/questoes/687475","page":35,"prompt":"Considere a proposição: “Se um candidato estudar adequadamente, então ele passará em um concurso”. Portanto, com base nesta proposição, é correto afirmar:","options":{"A":"Todos os candidatos que não estudam adequadamente não passam em um concurso.","B":"Todos os candidatos que estudam adequadamente passam em um concurso.","C":"Havendo candidatos que passam em um concurso, certamente estudam adequadamente.","D":"É possível que existam candidatos que estudam adequadamente e não passam em um concurso.","E":"A maior parte dos candidatos que passam em um concurso estudam adequadamente."},"answer":"B","visualRequired":false},{"id":"tec-692900","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - AFRE GO/SEFAZ GO/2018","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":692900,"url":"https://www.tecconcursos.com.br/questoes/692900","page":35,"prompt":"Um dos diretores de uma pequena indústria têxtil fez a seguinte afirmação durante uma reunião da diretoria: Se todas as matérias-primas forem entregues no prazo e nenhuma máquina de tingimento sofrer avaria, então o setor de produção conseguirá atingir a meta de setembro. Ao final do mês, porém, constatou-se que a meta de setembro não foi atingida pelo setor de produção. Considerando que a análise do diretor estava certa, é correto concluir que, necessariamente,","options":{"A":"pelo menos uma matéria-prima não foi entregue no prazo ou uma máquina de tingimento sofreu avaria.","B":"nem todas as matérias-primas foram entregues no prazo e pelo menos uma máquina de tingimento sofreu avaria.","C":"as matérias-primas não foram entregues no prazo ou todas as máquinas de tingimento sofreram avaria.","D":"nenhuma matéria-prima foi entregue no prazo e pelo menos uma máquina de tingimento sofreu avaria.","E":"algumas matérias-primas foram entregues fora prazo, mas nenhuma máquina de tingimento sofreu avaria."},"answer":"A","visualRequired":false},{"id":"tec-731081","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - POU (EMAE)/EMAE/2018","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":731081,"url":"https://www.tecconcursos.com.br/questoes/731081","page":35,"prompt":"Admita como verdadeiras as seguintes premissas: − Todos os minerais são flores. − Só existem três tipos de flores: as brancas, as vermelhas e as verdes. Cada uma das alternativas a seguir apresenta uma nova premissa que, como as anteriores, deve ser considerada verdadeira. Dessa forma, a alternativa que apresenta uma conclusão logicamente decorrente do trio de premissas é:","options":{"A":"Ratos são minerais. Logo, existem ratos brancos.","B":"Ratos não são minerais. Logo, nenhum rato é branco, ou vermelho, ou verde.","C":"Ratos são minerais. Logo, nenhum rato é azul.","D":"Ratos são flores. Logo, ratos são minerais.","E":"Ratos são flores. Logo, alguns ratos são verdes."},"answer":"C","visualRequired":false},{"id":"tec-732941","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Ana Min (MPE PE)/MPE PE/Jurídica/2018","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":732941,"url":"https://www.tecconcursos.com.br/questoes/732941","page":35,"prompt":"Suponha que sejam verdadeiras as premissas seguintes, mesmo que você não concorde com elas. − A maior parte dos cientistas não é constituída por pessoas ricas. − Muitas pessoas que não são ricas se alimentam mal. − Todas as pessoas que se alimentam bem são saudáveis. Com base nas premissas dadas, pode-se concluir corretamente que","options":{"A":"Todos os cientistas, devido a seus conhecimentos científicos, se alimentam bem.","B":"Todas as pessoas ricas se alimentam bem.","C":"Todo cientista que se alimenta bem é saudável.","D":"A maior parte das pessoas ricas é saudável.","E":"Todos os cientistas que se alimentam mal não são saudáveis."},"answer":"C","visualRequired":false},{"id":"tec-733039","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Ana Min (MPE PE)/MPE PE/Auditoria/2018","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":733039,"url":"https://www.tecconcursos.com.br/questoes/733039","page":35,"prompt":"Considere como verdadeiras as premissas seguintes, mesmo que sejam absurdas. − Todo canadense tem antepassados ingleses. − Todo inglês tem antepassados saxões. − Existem alemães com antepassados ingleses. De acordo com as premissas dadas, entre as sentenças seguintes, a única FALSA é:","options":{"A":"Todo canadense tem antepassados saxões.","B":"Alguns alemães têm antepassados saxões.","C":"Quem não tem antepassados saxões não é inglês.","D":"Nenhum alemão tem antepassados saxões.","E":"Quem não tem antepassados ingleses não é canadense."},"answer":"D","visualRequired":false},{"id":"tec-785969","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Educ Soc (FCRIA)/FCRIA (AP)/Nível Médio/2018","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":785969,"url":"https://www.tecconcursos.com.br/questoes/785969","page":36,"prompt":"Quando afirmamos: “ Todo brasileiro é patriota”, então:","options":{"A":"Quem não é brasileiro não é patriota.","B":"Aquele que é patriota é brasileiro.","C":"Quem não é patriota não é brasileiro.","D":"Aquele que é patriota não é brasileiro.","E":"Nenhum brasileiro é patriota."},"answer":"C","visualRequired":false},{"id":"tec-988889","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Vest (IBMEC)/IBMEC/Direito/2018","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":988889,"url":"https://www.tecconcursos.com.br/questoes/988889","page":36,"prompt":"Considere a sentença declarativa: “Todas as rosas são vermelhas.” A negação desta sentença é:","options":{"A":"“Algumas rosas são vermelhas.”","B":"“Nenhuma rosa é vermelha.”","C":"“Existem rosas vermelhas.”","D":"“Não existem rosas vermelhas.”","E":"“Existem rosas que não são vermelhas.”"},"answer":"E","visualRequired":false},{"id":"tec-456078","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - AJ TRT11/TRT 11/Apoio Especializado/Tecnologia da Informação/2017","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":456078,"url":"https://www.tecconcursos.com.br/questoes/456078","page":36,"prompt":"Dos funcionários do almoxarifado de uma empresa, todos aqueles que sabem mexer com planilha eletrônica também sabem mexer com processador de texto, e há funcionários que não mexem com planilha eletrônica nem com processador de texto. A respeito desses funcionários, é correto afirmar que quem","options":{"A":"não mexe com planilha eletrônica também não mexe com processador de texto.","B":"não mexe com processador de texto também não mexe com planilha eletrônica.","C":"não mexe com planilha eletrônica, mexe com processador de texto.","D":"mexe com processador de texto também mexe com planilha eletrônica.","E":"mexe com processador de texto, não mexe com planilha eletrônica."},"answer":"B","visualRequired":false},{"id":"tec-476710","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - AJ TRT24/TRT 24/Administrativa/\"Sem Especialidade\"/2017","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":476710,"url":"https://www.tecconcursos.com.br/questoes/476710","page":36,"prompt":"Uma afirmação que corresponda à negação lógica da afirmação: todos os programas foram limpos e nenhum vírus permaneceu, é:","options":{"A":"Se pelo menos um programa não foi limpo, então algum vírus não permaneceu.","B":"Existe um programa que não foi limpo ou pelo menos um vírus permaneceu.","C":"Nenhum programa foi limpo e todos os vírus permaneceram.","D":"Alguns programas foram limpos ou algum vírus não permaneceu.","E":"Se algum vírus permaneceu, então nenhum programa foi limpos."},"answer":"B","visualRequired":false},{"id":"tec-488329","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Ag FRT (ARTESP)/ARTESP/Técnico em Contabilidade - Administração/2017","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":488329,"url":"https://www.tecconcursos.com.br/questoes/488329","page":36,"prompt":"A afirmação que corresponde à negação lógica da frase ‘Vendedores falam muito e nenhum estudioso fala alto’ é","options":{"A":"‘ Nenhum vendedor fala muito e todos os estudiosos falam alto’.","B":"‘ Vendedores não falam muito e todos os estudiosos falam alto’.","C":"‘ Se os vendedores não falam muito, então os estudiosos não falam alto’.","D":"‘ Pelo menos um vendedor não fala muito ou todo estudioso fala alto’.","E":"‘ Vendedores não falam muito ou pelo menos um estudioso fala alto’."},"answer":"E","visualRequired":false},{"id":"tec-546941","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Tec (DPE RS)/DPE RS/Administrativa/2017","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":546941,"url":"https://www.tecconcursos.com.br/questoes/546941","page":36,"prompt":"Em uma escola há professor de química que é professor de física, mas não todos. Também há professor de matemática que é professor de física, mas não todos. Não há professor de matemática que seja professor de química. Não há professor de física que seja apenas professor de física. Nessa escola,","options":{"A":"todos os professores de física são professores de química.","B":"qualquer professor de matemática é professor de química.","C":"os professores de matemática que não são professores de química são professores de física.","D":"há professores de química que são professores de matemática e de física.","E":"qualquer professor de física que é professor de matemática, não é professor de química."},"answer":"E","visualRequired":false},{"id":"tec-584662","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - TJ TST/TST/Administrativa/\"Sem Especialidade\"/2017","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":584662,"url":"https://www.tecconcursos.com.br/questoes/584662","page":37,"prompt":"Considere como verdadeira a proposição: “Nenhum matemático é não dialético”. Laura enuncia que tal proposição implica, necessariamente, que I. se Carlos é matemático, então ele é dialético. II. se Pedro é dialético, então é matemático. III. se Luiz não é dialético, então não é matemático. IV. se Renato não é matemático, então não é dialético. Das implicações enunciadas por Laura, estão corretas APENAS","options":{"A":"I e III.","B":"I e II.","C":"III e IV.","D":"II e III.","E":"II e IV."},"answer":"A","visualRequired":false},{"id":"tec-357270","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - TJ TRF3/TRF 3/Apoio Especializado/Edificações/2016","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":357270,"url":"https://www.tecconcursos.com.br/questoes/357270","page":37,"prompt":"Se “ todo engenheiro é bom em matemática” e “algum engenheiro é físico”, conclui-se corretamente que","options":{"A":"todo físico é bom em matemática.","B":"certos bons em matemática não são físicos.","C":"existem bons em matemática que são físicos.","D":"certos físicos não são bons em matemática.","E":"não há engenheiros que sejam físicos."},"answer":"C","visualRequired":false},{"id":"tec-358385","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - AJ TRF3/TRF 3/Administrativa/2016","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":358385,"url":"https://www.tecconcursos.com.br/questoes/358385","page":37,"prompt":"Considere verdadeiras as afirmações abaixo. I. Todos os analistas que são advogados, são contadores também. II. Nem todos os contadores que são advogados, são analistas também. III. Há advogados que são apenas advogados e isso também acontece com alguns analistas, mas não acontece com qualquer um dos contadores. A partir dessas afirmações, é possível concluir corretamente que","options":{"A":"todo analista é advogado e é também contador.","B":"qualquer contador que seja analista é advogado também.","C":"existe analista que é advogado e não é contador.","D":"todo contador que é advogado é também analista.","E":"existe analista que não é advogado e existe contador que é analista."},"answer":"E","visualRequired":false},{"id":"tec-369534","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - PS (ELETROSUL)/ELETROSUL/Informática/2016","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":369534,"url":"https://www.tecconcursos.com.br/questoes/369534","page":37,"prompt":"Do ponto de vista da lógica, a negação da frase “alguns dos meus irmãos não vão ao cinema nos sábados à tarde” é","options":{"A":"excetuando um dos meus irmãos, os demais vão ao cinema nos sábados à tarde.","B":"alguns dos meus irmãos vão ao cinema nos sábados à tarde.","C":"todos os meus irmãos não vão ao cinema nos sábados à tarde.","D":"todos os meus irmãos vão ao cinema nos sábados à tarde.","E":"somente um dos meus irmãos não vai ao cinema nos sábados à tarde."},"answer":"D","visualRequired":false},{"id":"tec-375755","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Ana (COPERGÁS)/COPERGÁS/Tecnologia da Informação/2016","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":375755,"url":"https://www.tecconcursos.com.br/questoes/375755","page":37,"prompt":"É verdade que todo engenheiro sabe matemática. É verdade que há pessoas que sabem matemática e não são engenheiros. É verdade que existem administradores que sabem matemática. A partir dessas afirmações é possível concluir corretamente que","options":{"A":"qualquer engenheiro é administrador.","B":"todos os administradores sabem matemática.","C":"alguns engenheiros não sabem matemática.","D":"o administrador que sabe matemática é engenheiro.","E":"o administrador que é engenheiro sabe matemática."},"answer":"E","visualRequired":false},{"id":"tec-375882","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Tec Op (COPERGÁS)/COPERGÁS/Mecânico/2016","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":375882,"url":"https://www.tecconcursos.com.br/questoes/375882","page":38,"prompt":"É verdade que existem programadores que não gostam de computadores. A partir dessa afirmação é correto concluir que","options":{"A":"qualquer pessoa que não gosta de computadores é um programador.","B":"todas as pessoas que gostam de computadores não são programadores.","C":"dentre aqueles que não gostam de computadores, alguns são programadores.","D":"para ser programador é necessário gostar de computador.","E":"qualquer pessoa que gosta de computador será um bom programador."},"answer":"C","visualRequired":false},{"id":"tec-410512","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - ALegis (ALMS)/ALMS/Administrador/2016","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":410512,"url":"https://www.tecconcursos.com.br/questoes/410512","page":38,"prompt":"Quanto a dominar as habilidades A, B, C, D e E é sabido que há quem domine apenas uma dessas habilidades e isso acontece com as habilidades A, C e D. Há quem domine exatamente duas dessas habilidades e isso acontece com as habilidades, A e B, A e C, C e D, D e E. Dominar exatamente três dessas habilidades só acontece com as habilidades A e B e C. Não há quem domine mais do que três dessas habilidades. A partir dessas informações, é correto concluir que","options":{"A":"qualquer um que domine a habilidade B também domina a habilidade C.","B":"há quem domine a habilidade E e também a habilidade C.","C":"todos os que dominam a habilidade A também dominam a habilidade B.","D":"não há quem domine B e C que não domine A.","E":"poucos dominam exatamente as duas habilidades B e E."},"answer":"D","visualRequired":false},{"id":"tec-426186","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Moto (CREMESP)/CREMESP/2016","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":426186,"url":"https://www.tecconcursos.com.br/questoes/426186","page":38,"prompt":"Considere as afirmações: I. A maioria dos motoristas são habilitados. II. Alguns bons motoristas não são habilitados. A partir dessas afirmações é correto concluir que","options":{"A":"todos os motoristas são habilitados.","B":"qualquer motorista não habilitado não é bom motorista.","C":"não há bom motorista habilitado.","D":"há motoristas não habilitados.","E":"metade dos motoristas são habilitados."},"answer":"D","visualRequired":false},{"id":"tec-426243","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Op CC (CREMESP)/CREMESP/2016","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":426243,"url":"https://www.tecconcursos.com.br/questoes/426243","page":38,"prompt":"Em certa cidade, foi realizada uma pesquisa para saber quais eram os meios de transporte comumente utilizados pelos habitantes em seu dia a dia: automóvel, metrô, ônibus e bicicleta. O resumo dos resultados diz, dentre outras coisas, que: − Há os que andam exclusivamente de ônibus, os que andam exclusivamente de automóvel e os que andam exclusivamente de metrô. − Ninguém anda exclusivamente de bicicleta. − Ninguém que anda de automóvel usa ônibus. − Dentre os que andam de bicicleta, há os que também usam metrô, os que também usam ônibus e os que também usam ambos (metrô e ônibus). − Dentre os que andam de automóvel, há os que também usam metrô, os que também usam bicicleta e os que também usam ambos (metrô e bicicleta). Os resultados da pesquisa poderiam ser representados no diagrama abaixo, no qual os números estão apenas nomeando as regiões (não indicam quantidades): Assim, pelas afirmações expostas acerca dos resultados da pesquisa, é possível concluir que algumas regiões do diagrama ficariam vazias. São todas elas apenas as que estão indicadas pelos números","options":{"A":"1, 9, 10 e 12.","B":"1, 10 e 13.","C":"9, 10, 12 e 13.","D":"9, 10 e 12.","E":"1, 9, 10, 12 e 13"},"answer":"E","visualRequired":true},{"id":"tec-428578","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Adv Jr (METRO SP)/METRO SP/2016","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":428578,"url":"https://www.tecconcursos.com.br/questoes/428578","page":39,"prompt":"Ao considerar a afirmação: “todos os motoristas habilitados são habilidosos”, como sendo uma afirmação falsa, então é verdade que","options":{"A":"os motoristas não habilitados são habilidosos.","B":"os motoristas habilidosos não são habilitados.","C":"há motorista habilitado que não é habilidoso.","D":"a maioria dos motoristas habilitados não são habilidosos.","E":"há motorista habilidoso que não é habilitado."},"answer":"C","visualRequired":false},{"id":"tec-428580","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Adv Jr (METRO SP)/METRO SP/2016","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":428580,"url":"https://www.tecconcursos.com.br/questoes/428580","page":39,"prompt":"Considere as afirmações verdadeiras: I. Qualquer animal cachorro tem quatro patas. II. Nem todos os animais tem quatro patas. III. Há animais de quatro patas que são vertebrados. IV. As aves possuem apenas duas patas. A partir dessas informações é correto concluir que","options":{"A":"há ave que possui quatro patas.","B":"as aves não são animais vertebrados.","C":"os cachorros não são vertebrados.","D":"as aranhas são animais vertebrados.","E":"os cachorros não são aves."},"answer":"E","visualRequired":false},{"id":"tec-429011","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Aux Enf T (METRO SP)/METRO SP/2016","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":429011,"url":"https://www.tecconcursos.com.br/questoes/429011","page":39,"prompt":"Para confirmar que a afirmação “Nenhum homem é honesto” é uma afirmação falsa, é necessário e suficiente encontrar","options":{"A":"dez homens honestos.","B":"um homem desonesto.","C":"mais da metade dos homens honestos.","D":"um homem honesto.","E":"todos os homens honestos."},"answer":"D","visualRequired":false},{"id":"tec-439658","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - TJ TRT20/TRT 20/Administrativa/\"Sem Especialidade\"/2016","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":439658,"url":"https://www.tecconcursos.com.br/questoes/439658","page":39,"prompt":"Considere que todo técnico sabe digitar. Alguns desses técnicos sabem atender ao público externo e outros desses técnicos não sabem atender ao público externo. A partir dessas afirmações é correto concluir que","options":{"A":"os técnicos que sabem atender ao público externo não sabem digitar.","B":"os técnicos que não sabem atender ao público externo não sabem digitar.","C":"qualquer pessoa que sabe digitar também sabe atender ao público externo.","D":"os técnicos que não sabem atender ao público externo sabem digitar.","E":"os técnicos que sabem digitar não atendem ao público externo."},"answer":"D","visualRequired":false},{"id":"tec-618905","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Ap (METRO SP)/METRO SP/2016","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":618905,"url":"https://www.tecconcursos.com.br/questoes/618905","page":40,"prompt":"A partir da afirmação: − Dentre um grupo de 100 jogadores de futebol, alguns são baixos. − é correto concluir que","options":{"A":"todos esses 100 jogadores são baixos.","B":"é certo que mais da metade desses jogadores não são baixos.","C":"é certo que menos da metade desses jogadores não são baixos.","D":"é possível que não haja qualquer jogador baixo.","E":"é possível serem apenas dois jogadores baixos."},"answer":"E","visualRequired":false},{"id":"tec-621662","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Ag Mec MA (SANASA)/SANASA/Motor Diesel/2016","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":621662,"url":"https://www.tecconcursos.com.br/questoes/621662","page":40,"prompt":"Alguns animais domésticos tem quatro patas. Em volta da casa do meu avô eu vi dois animais de quatro patas. Meu avô tem um cachorro. A partir dessas afirmações é correto concluir que","options":{"A":"se não vi o cachorro do meu avô, então os animais que vi não são domésticos.","B":"meu avô possui dois cachorros.","C":"um dos animais que vi é um animal doméstico.","D":"se vi o cachorro do meu avô, então o outro animal pode ser doméstico.","E":"nenhum dos animais que vi é animal doméstico."},"answer":"D","visualRequired":false},{"id":"tec-258726","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Tec (CNMP)/CNMP/Apoio Técnico Administrativo/Administração/2015","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":258726,"url":"https://www.tecconcursos.com.br/questoes/258726","page":40,"prompt":"Nenhum bom investigador é acrítico (não crítico), e existem bons investigadores que são racionais. Do ponto de vista da lógica, utilizando apenas as informações dessa implicação segue, necessariamente, que alguns","options":{"A":"racionais são acríticos.","B":"racionais são críticos.","C":"críticos não são racionais.","D":"bons investigadores não são racionais.","E":"investigadores não são bons."},"answer":"B","visualRequired":false},{"id":"tec-263312","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - JATTE (SEFAZ PE)/SEFAZ PE/2015","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":263312,"url":"https://www.tecconcursos.com.br/questoes/263312","page":40,"prompt":"Na Escola Recife, todo professor de Desenho Geométrico ensina também Matemática. Alguns coordenadores, mas não todos, são professores de Matemática. Além disso, todos os pedagogos da Escola Recife são coordenadores, mas nenhum deles ensina Desenho Geométrico. Somente com estas informações, é correto concluir que na Escola Recife, necessariamente,","options":{"A":"pelo menos um pedagogo é professor de Matemática.","B":"nem todo pedagogo é professor de Matemática.","C":"existe um professor de Desenho Geométrico que não é coordenador.","D":"existe um coordenador que não é professor de Desenho Geométrico.","E":"todo pedagogo é professor de Desenho Geométrico."},"answer":"D","visualRequired":false},{"id":"tec-283229","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - TCE (TCE-CE)/TCE CE/Controle Externo/Auditoria de Tecnologia da Informação/2015","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":283229,"url":"https://www.tecconcursos.com.br/questoes/283229","page":40,"prompt":"Considere como verdadeiras as afirmações: − Todo programador sabe inglês. − Todo programador conhece informática. − Alguns programadores não são organizados. A partir dessas afirmações é correto concluir que","options":{"A":"todos que sabem inglês são programadores.","B":"pode existir alguém que conheça informática e não seja programador.","C":"todos que conhecem informática são organizados.","D":"todos que conhecem informática sabem inglês.","E":"pode existir programadores organizados que não sabem inglês."},"answer":"B","visualRequired":false},{"id":"tec-299489","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - TJ TRT4/TRT 4/Apoio Especializado/Tecnologia da Informação/2015","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":299489,"url":"https://www.tecconcursos.com.br/questoes/299489","page":41,"prompt":"Dadas apenas as proposições “ nenhum contador é médico” e “ algum médico é biólogo”, do ponto de vista da lógica é válido concluir que","options":{"A":"algum biólogo não é contador.","B":"algum biólogo é contador.","C":"todo biólogo é médico.","D":"algum biólogo é contador e não é médico.","E":"existe biólogo que não é médico."},"answer":"A","visualRequired":false},{"id":"tec-326016","module":"M05","origin":"FCC legado (gabarito não revisado)","bank":"FCC","source":"FCC - Aux Tec Fis (TCE-SP)/TCE SP/\"Sem Área\"/2015","topic":"Raciocínio Lógico - Diagramas Lógicos, Proposições Categóricas, Negação de Quantificadores","tecId":326016,"url":"https://www.tecconcursos.com.br/questoes/326016","page":41,"prompt":"É verdade que nenhum professor é rico. É verdade que algum advogado é rico. A partir dessas afirmações, é verdadeiro concluir, corretamente, que","options":{"A":"nenhum advogado é professor.","B":"algum advogado não é professor.","C":"todo advogado não é professor.","D":"algum advogado é professor.","E":"todo advogado é professor."},"answer":"B","visualRequired":false}];
